NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Judges'

CHAPTERS = {
    1: {
        1: 'Torej po Józuetovi smrti se je pripetilo, da so Izraelovi otroci vprašali Gospoda, rekoč: »Kdo bo za nas najprej šel gor zoper Kánaance, da se bori zoper njih?«',
        2: 'Gospod je rekel: »Juda bo šel gor. Glejte, deželo sem izročil v njegovo roko.«',
        3: 'Juda je svojemu bratu Simeonu rekel: »Pridi gor z menoj v moj žreb, da se bova lahko borila zoper Kánaance in prav tako bom tudi jaz šel s teboj v tvoj žreb.« Tako je Simeon odšel z njim.',
        4: 'Juda je odšel gor in Gospod je Kánaance in Perizéjce izročil v njuno roko in izmed njih sta v Bezeku usmrtila deset tisoč mož.',
        5: 'V Bezeku sta našla Adoní Bezeka in se borila zoper njega ter usmrtila Kánaance in Perizéjce.',
        6: 'Toda Adoní Bezek je pobegnil in sledila sta za njim, ga ujela ter odsekala njegova palca in velika prsta na njegovih stopalih.',
        7: 'Adoní Bezek je rekel: »Sedemdeset kraljev, ki imajo odsekane svoje palce in svoje palce na stopalih, je svojo hrano pobiralo pod mojo mizo. Kakor sem jaz storil, tako mi je Bog poplačal.« In odvedla sta ga v Jeruzalem in tam je umrl.',
        8: 'Torej Judovi otroci so se borili zoper Jeruzalem, ga zavzeli, udarili z ostrino meča in zažgali mesto.',
        9: 'Potem so Judovi otroci odšli dol, da se borijo zoper Kánaance, ki prebivajo na gori, na jugu in v dolini.',
        10: 'Juda je odšel zoper Kánaance, ki prebivajo v Hebrónu (torej ime Hebróna je bilo prej Kirját Arba) in usmrtili so Šešája, Ahimána in Talmája.',
        11: 'Od tam je odšel zoper prebivalce Debírja. Ime Debírja pa je bilo prej Kirját Sefer.',
        12: 'Kaléb je rekel: »Kdor udari Kirját Sefer in ga zavzame, njemu bom dal svojo hčer Ahso za ženo.«',
        13: 'Zavzel ga je Kenázov sin Otniél, Kalébov mlajši brat in dal mu je svojo hčer Ahso za ženo.',
        14: 'Ko je prišla k njemu se je pripetilo, da ga je primorala, da prosi od svojega očeta polje in razjahala je svojega osla in Kaléb ji je rekel: »Kaj hočeš?«',
        15: 'Rekla mu je: »Daj mi blagoslov, kajti dal si mi južno deželo; daj mi tudi vodne izvire.« In Kaléb ji je dal gornje izvire in spodnje izvire.',
        16: 'Otroci Kenéjca, Mojzesovega tasta, so z Judovimi otroki odšli gor iz mesta palmovih dreves v Judovo divjino, ki leži na jugu Aráda in odšli so ter prebivali med ljudstvom.',
        17: 'Juda je odšel s svojim bratom Simeonom in usmrtili so Kánaance, ki naseljujejo Cefát in ga popolnoma uničili. Ime mesta se je imenovalo Horma.',
        18: 'Juda je zavzel tudi Gazo z njenimi pokrajinami, Aškelón z njegovimi pokrajinami in Ekrón z njegovimi pokrajinami.',
        19: 'Gospod je bil z Judom in napodil je prebivalce gore, toda ni mogel napoditi prebivalcev doline, ker so imeli železne vozove.',
        20: 'Hebrón so dali Kalébu, kakor je rekel Mojzes, in od tam je izgnal tri Anákove sinove.',
        21: 'Benjaminovi otroci pa niso napodili Jebusejcev, ki so naseljevali Jeruzalem, temveč Jebusejci prebivajo z Benjaminovimi otroki v Jeruzalemu do današnjega dne.',
        22: 'Jožefova hiša, tudi oni so se dvignili zoper Betel in Gospod je bil z njimi.',
        23: 'Jožefova hiša je poslala, da razišče Betel. (Torej ime mesta je bilo prej Luz.)',
        24: 'Ogledniki so videli moža priti iz mesta in mu rekli: »Pokaži nam, prosimo te, vhod v mesto, mi pa ti bomo izkazali usmiljenje.«',
        25: 'Ko jim je ta pokazal vhod v mesto, potem so mesto udarili z ostrino meča, toda spustili so moža in vso njegovo družino.',
        26: 'Mož je odšel v deželo Hetejcev, zgradil mesto in njegovo ime imenoval Luz, kar je njegovo ime do današnjega dne.',
        27: 'Niti Manáse ni napodil prebivalcev Bet Šeána in njegovih mest, niti Taanáha in njegovih mest, niti prebivalcev Dora in njegovih mest, niti prebivalcev Jibleáma in njegovih mest, niti prebivalcev Megída in njenih mest, temveč so Kánaanci hoteli prebivati v tej deželi.',
        28: 'Pripetilo se je, ko je bil Izrael močan, da so Kánaance podvrgli davku, niso pa jih popolnoma pognali ven.',
        29: 'Niti ni Efrájim napodil Kánaancev, ki prebivajo v Gezerju, temveč Kánaanci prebivajo med njimi v Gezerju.',
        30: 'Niti ni Zábulon napodil prebivalcev Kitróna niti prebivalcev Nahalóla, temveč so Kánaanci prebivali med njimi in postali so davkoplačevalci.',
        31: 'Niti ni Aser napodil prebivalcev Aka, niti prebivalcev Sidóna, niti Ahalaba, niti Ahzíba, niti Helbe, niti Aféke, niti Rehóba,',
        32: 'temveč so Aserjevci prebivali med Kánaanci, prebivalci dežele, kajti niso jih pognali ven.',
        33: 'Niti ni Neftáli napodil prebivalcev Bet Šemeša niti prebivalcev Bet Anáta, temveč je prebival med Kánaanci, prebivalci dežele. Kljub temu so jim prebivalci Bet Šemeša in Bet Anáta postali davkoplačevalci.',
        34: 'Amoréjci pa so Danove otroke potisnili na goro, kajti niso jim hoteli pustiti, da pridejo dol k dolini,',
        35: 'temveč so Amoréjci hoteli prebivati na gori Heres v Ajalónu in v Šaalbímu. Vendar je roka Jožefove hiše prevladala, tako da so postali davkoplačevalci.',
        36: 'Pokrajina Amoréjcev je bila od vzpona k Akrabímu, od skale in navzgor.',
    },
    2: {
        1: 'Gospodov angel je prišel gor od Gilgála k Bohímu in rekel: »Primoral sem vas iti gor, ven iz Egipta in vas privedel v deželo, ki sem jo prisegel vašim očetom. Rekel sem: ›Nikoli ne bom prelomil svoje zaveze z vami.',
        2: 'In vi ne boste sklenili nobene zaveze s prebivalci te dežele; zrušili boste njihove oltarje.‹ Toda niste ubogali mojega glasu. Zakaj ste to storili?‹',
        3: 'Zato sem tudi rekel: ›Ne bom jih pognal izpred vas, temveč vam bodo kakor trni na vaših straneh in njihovi bogovi vam bodo zanka.‹«',
        4: 'Pripetilo se je, ko je Gospodov angel te besede povedal vsem Izraelovim otrokom, da je ljudstvo povzdignilo svoj glas in zajokalo.',
        5: 'Ime tega kraja so imenovali Bohím in tam so darovali Gospodu.',
        6: 'Ko je Józue pustil ljudstvu oditi, so Izraelovi otroci odšli, vsak mož v svojo dediščino, da deželo vzamejo v last.',
        7: 'Ljudstvo je služilo Gospodu vse Józuetove dni in vse dni starešin, ki so preživeli Józueta, ki so videli vsa velika Gospodova dela, ki jih je storil za Izrael.',
        8: 'Nunov sin Józue, Gospodov služabnik, je umrl, star sto deset let.',
        9: 'Pokopali so ga na meji njegove dediščine, v Timnát Heresu, na gori Efrájim, na severni strani Gáaševega hriba.',
        10: 'Tudi ves ta rod je bil zbran k svojim očetom in tam je za njimi vstal drug rod, ki ni poznal Gospoda niti še ne del, ki jih je ta storil za Izrael.',
        11: 'Izraelovi otroci so počeli zlo v Gospodovih očeh in služili Báalom.',
        12: 'Zapustili so Gospoda, Boga svojih očetov, ki jih je privedel iz egiptovske dežele in sledili drugim bogovom, bogovom ljudstev, ki so bili okoli njih, se jim priklanjali in Gospoda izzivali k jezi.',
        13: 'Zapustili so Gospoda in služili Báalu in Astarti.',
        14: 'Gospodova jeza je bila vroča zoper Izrael in izročil jih je v roke plenilcev, ki so jih oplenili in jih prodal v roke njihovih sovražnikov naokoli, tako da ne bi mogli več obstati pred svojimi sovražniki.',
        15: 'Kamorkoli so odšli, je bila zoper njih Gospodova roka za zlo, kakor je Gospod rekel in kakor jim je Gospod prisegel. Bili so silno stiskani.',
        16: 'Kljub temu je Gospod dvignil sodnike, ki so jih osvobajali iz roke tistih, ki so jih plenili.',
        17: 'Vendar niso hoteli prisluhniti svojim sodnikom, temveč so se odšli vlačugat za drugimi bogovi in se jim priklanjali. Hitro so se obrnili iz poti, po kateri so hodili njihovi očetje z uboganjem Gospodovih zapovedi, toda oni niso tako storili.',
        18: 'Ko jim je Gospod dvignil sodnike, potem je bil Gospod s sodnikom in jih vse sodnikove dni osvobajal iz roke njihovih sovražnikov, kajti to je pokesalo Gospoda zaradi njihovega stokanja, zaradi razloga tistih, ki so jih zatirali in jih slabili.',
        19: 'Pripetilo pa se je, ko je bil sodnik mrtev, da so se vrnili in se izpridili bolj kakor njihovi očetje v sledenju drugim bogovom, da jim služijo in se jim priklanjajo. Niso odnehali od svojih lastnih početij niti od svoje trmoglave poti.',
        20: 'Gospodova jeza je bila vroča zoper Izrael in rekel je: »Zato, ker je to ljudstvo prekršilo mojo zavezo, ki sem jo zapovedal njihovim očetom in niso prisluhnili mojemu glasu,',
        21: 'odslej tudi jaz pred njimi ne bom podil kateregakoli izmed narodov, ki jih je pustil Józue, ko je umrl,',
        22: 'da bom lahko po njih preizkusil Izraela, če se bodo držali Gospodove poti, da hodijo po njej, kakor so se je držali njihovi očetje ali ne.«',
        23: 'Zato je Gospod pustil tiste narode, ne da bi jih naglo pognal ven niti jih ni izročil v Józuetovo roko.',
    },
    3: {
        1: 'Torej to so narodi, ki jih je pustil Gospod, da z njimi preizkusi Izraela, torej tiste iz Izraela, ki niso poznali vseh kánaanskih vojn,',
        2: 'samo da bi rodovi Izraelovih otrok lahko vedeli, da jih naučijo vojne, vsaj tiste, ki prej niso ničesar vedeli o tem,',
        3: 'namreč pet filistejskih knezov in vse Kánaance, Sidónce in Hivéjce, ki so prebivali na gori Libanon, od gore Báal Hermon, do vhoda v Hamát.',
        4: 'Bili so, da z njimi preizkusi Izraela, da spozna, ali bodo prisluhnili Gospodovim zapovedim, ki jih je po Mojzesovi roki zapovedal njihovim očetom.',
        5: 'Izraelovi otroci so prebivali med Kánaanci, Hetejci, Amoréjci, Perizéjci, Hivéjci in Jebusejci',
        6: 'in jemali so njihove hčere, da so postale njihove žene in svoje hčere so dajali njihovim sinovom in služili njihovim bogovom.',
        7: 'Izraelovi otroci so počeli zlo v Gospodovih očeh in pozabili Gospoda, svojega Boga in služili Báalom in ašeram.',
        8: 'Zato je bila Gospodova jeza vroča zoper Izrael in jih je prodal v roko Kušán Rišatájima, kralja Mezopotamije in Izraelovi otroci so osem let služili Kušán Rišatájimu.',
        9: 'Ko so Izraelovi otroci vpili h Gospodu, je Gospod Izraelovim otrokom dvignil osvoboditelja, ki jih je osvobodil, Kenázovega sina Otniéla, Kalébovega mlajšega brata.',
        10: 'Gospodov Duh je prišel nadenj in sodil je Izraelu in odšel ven na vojsko in Gospod je izročil Kušán Rišatájima, kralja Mezopotamije, v njegovo roko in njegova roka je prevladala zoper Kušán Rišatájima.',
        11: 'Dežela je imela štirideset let počitek in Kenázov sin Otniél je umrl.',
        12: 'Izraelovi otroci pa so ponovno počeli zlo v Gospodovih očeh in Gospod je zoper Izraela okrepil moábskega kralja Eglóna, ker so počeli zlo v Gospodovih očeh.',
        13: 'K sebi je zbral otroke Amóna in Amáleka ter odšel in udaril Izrael in v last vzel mesto palmovih dreves.',
        14: 'Tako so Izraelovi otroci osemnajst let služili moábskemu kralju Eglónu.',
        15: 'Toda ko so Izraelovi otroci klicali h Gospodu, jim je Gospod dvignil osvoboditelja, Gerájevega sina Ehúda, Benjaminovca, moža, ki je bil levičen in po njem so Izraelovi otroci poslali darilo moábskemu kralju Eglónu.',
        16: 'Toda Ehúd si je naredil bodalo, ki je imelo dve ostrini, komolec dolgo in opasal si ga je pod oblačilo, na svoje desno stegno.',
        17: 'In prinesel je darilo moábskemu kralju Eglónu. Eglón pa je bil zelo debel mož.',
        18: 'Ko je končal s ponujanjem darila, je ljudstvo, ki je nosilo darilo, odposlal proč.',
        19: 'Toda on sam se je ponovno obrnil od klesancev, ki so bili pri Gilgálu in rekel: »Zate imam skrivno naročilo, oh kralj.« Ta je rekel: »Molči.« In vsi, ki so stali pri njem, so odšli od njega.',
        20: 'Ehúd je prišel k njemu in ta je sedel v poletni dvorani, ki jo je imel samo zase. Ehúd je rekel: »Zate imam sporočilo od Boga.« In ta je vstal iz svojega sedeža.',
        21: 'Ehúd je svojo levo roko iztegnil naprej, vzel bodalo s svojega desnega stegna in ga zabodel v njegov trebuh.',
        22: '§ Tudi ročaj je šel noter za rezilom in maščoba se je zaprla na rezilu, tako da bodala ni mogel izvleči iz njegovega trebuha in ven je prišla umazanija.',
        23: 'Potem je Ehúd šel naprej skozi preddverje ter za seboj zaprl vrata dvorane in jih zaklenil.',
        24: 'Ko je odšel ven, so prišli njegovi služabniki in glej, ko so videli, da so bila vrata dvorane zaklenjena, so rekli: »Zagotovo v svoji poletni sobi pokriva svoja stopala.«',
        25: 'Obotavljali so se, dokler jih ni postalo sram in glej, vrat dvorane ni odprl. Zato so vzeli ključ in jih odprli in glej, njihov gospod je mrtev ležal na zemlji.',
        26: 'Ehúd pa je pobegnil, medtem ko so se zadrževali in šel onkraj klesancev in pobegnil v Seíro.',
        27: 'Pripetilo se je, ko je prišel, da je na gori Efrájim zatrobil na šofar in Izraelovi otroci so se z njim spustili z gore in on [sam] je bil pred njimi.',
        28: 'Rekel jim je: »Sledite za menoj, kajti Gospod je vaše sovražnike Moábce izročil v vašo roko.« Odšli so dol za njim in zavzeli jordanske prehode proti Moábu in nobenemu človeku niso pustili iti čez.',
        29: 'Ob tistem času so iz Moába usmrtili okoli deset tisoč mož, vse krepke in vse junaške može; in tam ni utekel niti [en] človek.',
        30: 'Tako je bil tisti dan Moáb podjarmljen pod Izraelovo roko. In dežela je imela osemdeset let počitek.',
        31: 'Za njim je bil Anátov sin Šamgár, ki je z volovsko palico z bodico izmed Filistejcev usmrtil šeststo mož. Tudi on je osvobodil Izraela.',
    },
    4: {
        1: 'Ko je bil Ehúd mrtev, so Izraelovi otroci ponovno počeli zlo v Gospodovih očeh.',
        2: 'Gospod jih je prodal v roko kánaanskega kralja Jabína, ki je kraljeval v Hacórju, katerega poveljnik vojske je bil Siserá, ki je prebival v Haróšetu poganov.',
        3: 'Izraelovi otroci so vpili h Gospodu, kajti imel je devetsto bojnih vozov iz železa in dvajset let je mogočno zatiral Izraelove otroke.',
        4: 'Ob tistem času je Izraelu sodila prerokinja Debóra, Lapidótova žena.',
        5: 'Prebivala je pod Debórinim palmovim drevesom med Ramo in Betelom, na gori Efrájim in Izraelovi otroci so prihajali gor k njej za sodbo.',
        6: 'Poslala je in poklicala Abinóamovega sina Baráka iz Kedeš-Neftálija in mu rekla: »Ali ni Gospod, Izraelov Bog, zapovedal, rekoč: ›Pojdi in odpravi se proti gori Tabor in s seboj vzemi deset tisoč mož izmed Neftálijevih otrok in Zábulonovih otrok?‹',
        7: 'K tebi, k reki Kišón, bom pritegnila Siserája, poveljnika Jabínove vojske, z njegovimi bojnimi vozovi in njegovo množico in izročila ga bom v tvojo roko.«',
        8: 'Barák ji je rekel: »Če boš šla z menoj, potem bom šel, če pa ne boš šla z menoj, potem ne bom šel.«',
        9: 'Rekla je: »Zagotovo bom šla s teboj, vendar potovanje, na katero greš, ne bo v tvojo čast, kajti Gospod bo Siserája prodal v roko ženske.« Debóra je vstala in z Barákom odšla v Kedeš.',
        10: 'Barák je v Kedeš poklical Zábulona in Neftálija in ta je odšel gor z deset tisoč možmi ob svojih stopalih in Debóra je z njim odšla gor.',
        11: 'Torej Kenéjec Heber, ki je bil izmed otrok Mojzesovega tasta Hobába, se je oddvojil od Kenéjcev in si svoj šotor postavil na ravnini Caananím, ki je pri Kedešu.',
        12: 'Siseráju so naznanili, da je Abinóamov sin Barák odšel gor h gori Tabor.',
        13: 'Siserá je zbral skupaj vse svoje bojne vozove, devetsto železnih bojnih vozov in vse ljudstvo, ki je bilo z njim, od Haróšeta poganov do reke Kišón.',
        14: 'Debóra je rekla Baráku: »Vstani, kajti to je dan, na katerega je Gospod izročil Siserája v tvojo roko. Ali ni Gospod šel ven pred teboj?« Tako je Barák odšel dol z gore Tabor in deset tisoč mož za njim.',
        15: 'Gospod je pred Barákom z ostrino meča porazil Siserája, vse njegove bojne vozove in vso njegovo vojsko, tako da se je Siserá spustil iz svojega bojnega voza in pobegnil na svojih stopalih.',
        16: 'Toda Barák je zasledoval bojne vozove in vojsko do Haróšeta poganov in vsa Siserájeva vojska je padla na ostrino meča in niti mož ni preostal.',
        17: 'Vendar je Siserá na svojih stopalih pobegnil proč k šotoru Jaéle, žene Kenéjca Heberja, kajti mir je bil med Jabínom, kraljem Hacórja in hišo Kenéjca Heberja.',
        18: 'Jaéla je odšla ven, da sreča Siserája ter mu rekla: »Zavij noter, moj gospod, zavij noter k meni. Ne boj se.« Ko je zavil noter, k njej v šotor, ga je pokrila z ogrinjalom.',
        19: 'Rekel ji je: »Daj mi, prosim te, piti malo vode, kajti žejen sem.« Odprla je meh mleka, mu dala piti in ga pokrila.',
        20: 'Ponovno ji je rekel: »Stoj v vratih šotora in zgodilo se bo, ko pride katerikoli mož in od tebe poizveduje in reče: ›Ali je tam kakšen mož,‹ da boš rekla: ›Ne.‹',
        21: 'Potem je Heberjeva žena Jaéla vzela šotorski klin in v svojo roko vzela kladivo in po tiho odšla k njemu in klin zabila v njegova sènca in ga pritrdila k tlom, kajti trdno je zaspal in bil je izmučen. Tako je umrl.',
        22: 'Glej, ko je Barák zasledoval Siserája, je Jaéla prišla ven, da ga sreča ter mu rekla: »Pridi in pokazala ti bom moža, ki ga iščeš.« Ko je vstopil v njen šotor, glej, Siserá je ležal mrtev in klin je bil v njegovih sèncih.',
        23: 'Tako je Bog na ta dan pred Izraelovimi otroki podjarmil kánaanskega kralja Jabína.',
        24: 'Roka Izraelovih otrok je uspevala in prevladala zoper kánaanskega kralja Jabína, dokler niso uničili kánaanskega kralja Jabína.',
    },
    5: {
        1: 'Potem sta Debóra in Abinóamov sin Barák tisti dan zapela, rekoč:',
        2: '»Hvalite Gospoda za maščevanje Izraela, ko se je ljudstvo voljno darovalo.',
        3: 'Poslušajte, oh vi kralji, pazljivo prisluhnite, oh vi princi. Jaz, celó jaz, bom prepevala Gospodu. Prepevala bom hvalo Gospodu, Izraelovemu Bogu.',
        4: 'Gospod, ko si šel iz Seírja, ko si korakal ven iz edómskega polja, je zemlja trepetala in nebo je kapljalo, tudi oblaki so kapljali vodo.',
        5: 'Gore so se topile pred Gospodom, celó tisti Sinaj pred Gospodom, Izraelovim Bogom.',
        6: 'V dneh Anátovega sina Šamgárja, v dneh Jaéle, so bile glavne ceste prazne in popotniki so hodili po stranskih poteh.',
        7: 'Prebivalci vasi so prenehali, prenehali so v Izraelu, dokler nisem vstala jaz, Debóra, ki sem vstala, mati v Izraelu.',
        8: '§ Izbrali so nove bogove. Potem je bila vojna v velikih vratih. Ali sta bila ščit ali sulica videna med štiridesetimi tisoči v Izraelu?',
        9: 'Moje srce je [nagnjeno] k Izraelovim voditeljem, ki so se voljno darovali med ljudstvom. Blagoslavljajte Gospoda.',
        10: 'Govorite, vi, ki jahate na belih oslih, vi, ki sedite na sodbi in hodite po poti.',
        11: 'Tisti, ki so bili osvobojeni pred hrupom lokostrelcev na krajih zajemanj vode, bodo tam ponavljali Gospodova pravična dejanja, celó pravična dejanja do prebivalcev njegovih vasi v Izraelu. Potem bo Gospodovo ljudstvo šlo dol k velikim vratom.',
        12: 'Prebudi se, prebudi se, Debóra. Prebudi se, prebudi se, izusti pesem. Vstani Barák in vodí svoje ujeto ujetništvo, ti, Abinóamov sin.',
        13: 'Potem je naredil tistega, ki preostane, da ima gospostvo nad plemiči izmed ljudstva. Gospod me je naredil, da imam gospostvo nad mogočnimi.',
        14: 'Iz Efrájima je bila tam korenina tistih zoper Amáleka. Za teboj, Benjamin, med tvojim ljudstvom. Iz Mahírja so prišli dol voditelji in iz Zábulona tisti, ki vlečejo pisalo pisca.',
        15: 'Isahárjevi princi so bili z Debóro, celo Isahár in tudi Barák. Peš je bil poslan v dolino. Zaradi Rubenovih oddelkov so bile velike misli srca.',
        16: 'Zakaj ostajaš med ovčjimi stajami, da poslušaš blejanje tropov? Zaradi Rubenovih oddelkov so bila velika preiskovanja srca.',
        17: 'Gileád je prebival onkraj Jordana in zakaj je Dan ostal v ladjah? Aser je nadaljeval na morski obali in prebival v svojih vrzelih.',
        18: 'Zábulon in Neftáli sta bila ljudstvi, ki sta izpostavili svoja življenja smrti na visokih krajih polja.',
        19: 'Kralji so prišli in se bojevali, potem so se pri vodah Megída v Taanáhu bojevali kánaanski kralji; nobenega dobička od denarja niso vzeli.',
        20: 'Vojskovali so se z neba. Zvezde na svojih orbitah so se bojevale zoper Siserája.',
        21: 'Reka Kišón jih je odplavila, ta starodavna reka, reka Kišón. Oh moja duša, pomendrala si moč.',
        22: 'Potem so bila konjska kopita zlomljena zaradi razloga drvenj, drvenj njihovih mogočnih.',
        23: '›Prekolnite Meróz,‹ je rekel Gospodov angel, grenko prekolnite njegove prebivalce, ker niso prišli na pomoč Gospodu, na pomoč Gospodu zoper mogočnega.‹',
        24: 'Blagoslovljena nad ženami naj bo Jaéla, žena Kenéjca Heberja, blagoslovljena nad ženami naj bo v šotoru.',
        25: 'Prosil je vode in dala mu je mleko. V gosposki skledi je prinesla maslo.',
        26: 'Svojo roko je iztegnila h klinu in svojo desnico k delavčevemu kladivu in s kladivom je udarila Siserája, zdrobila mu je glavo, ko jo je predrla in udarila skozi njegova sènca.',
        27: 'Ob njenih stopalih se je upognil, padel je, ulegel se je. Ob njenih stopalih se je upognil, padel je. Kjer se je upognil, tam je mrtev padel dol.',
        28: 'Siserájeva mati je pogledala skozi okno in zaklicala skozi mrežo: ›Zakaj se njegov bojni voz tako dolgo mudi? Zakaj se mudijo kolesa njegovih bojnih vozov?‹',
        29: 'Njene modre gospe so ji odgovorile, da, sebi je vrnila odgovor:',
        30: '›Ali niso pohiteli? Ali niso razdelili plena; vsakemu možu gospodično ali dve. Siseráju plen številnih barv, plen številnih barv vezenine, številnih barv vezenine na obeh straneh, primerne za vratove tistih, ki jemljejo plen?‹',
        31: 'Tako naj vsi tvoji sovražniki propadejo, oh Gospod, toda naj bodo tisti, ki ga ljubijo, kakor sonce, ko vzide v svoji moči.« In dežela je imela štirideset let počitek.',
    },
    6: {
        1: 'Izraelovi otroci so v Gospodovih očeh počeli zlo in Gospod jih je [za] sedem let izročil v roko Midjáncev.',
        2: 'Roka Midjáncev je prevladala zoper Izraela in zaradi Midjáncev so si Izraelovi otroci naredili jame, ki so v gorah, votline in oporišča.',
        3: 'Bilo je tako, ko je Izrael sejal, da so prišli gor Midjánci, Amalečani in otroci vzhoda, celó ti so prišli gor zoper njih',
        4: 'in se utaborili zoper njih in uničili donos zemlje, dokler ne prideš do Gaze in za Izrael niso pustili nobene oskrbe, niti ovce, niti vola, niti osla.',
        5: 'Kajti gor so prišli s svojo živino in svojimi šotori in prišli so kakor kobilice zaradi množice, kajti tako njih kakor njihovih kamel je bilo brez števila in vstopili so v deželo, da jo uničijo.',
        6: 'Zaradi Midjáncev je bil Izrael silno obubožan in Izraelovi otroci so klicali h Gospodu.',
        7: 'Pripetilo se je, ko so zaradi Midjáncev Izraelovi otroci klicali h Gospodu,',
        8: 'da je Gospod k Izraelovim otrokom poslal preroka, ki jim je rekel: »Tako govori Gospod, Izraelov Bog: ›Privedel sem vas gor iz Egipta, vas izpeljal iz hiše sužnosti,',
        9: 'vas osvobodil iz roke Egipčanov in iz roke vseh, ki so vas zatirali in jih pregnal izpred vas in vam dal njihovo deželo',
        10: 'ter vam rekel: ›Jaz sem Gospod, vaš Bog. Ne bojte se bogov Amoréjcev, v katerih deželi prebivate.‹ Toda niste ubogali mojega glasu.‹«',
        11: 'Prišel je Gospodov angel in sedel pod hrast, ki je bil v Ofri, ki je pripadal Abiézerjevcu Joášu. Njegov sin Gideón je pri vinski stiskalnici mlatil pšenico, da jo skrije pred Midjánci.',
        12: 'Prikazal se mu je Gospodov angel ter mu rekel: » Gospod je s teboj, mogočen, hraber mož.«',
        13: 'Gideón mu je rekel: »Oh moj Gospod, če je z nami Gospod, zakaj nas je potem vse to doletelo? In kje so vsi njegovi čudeži, o katerih so nam povedali naši očetje, rekoč. ›Ali nas ni Gospod privedel gor iz Egipta? Toda sedaj nas je Gospod zapustil in nas izročil v roke Midjáncev.‹«',
        14: 'Gospod je pogledal nanj in rekel: »Pojdi v tej svoji moči in ti boš Izraela rešil iz roke Midjáncev. Ali te nisem jaz poslal?«',
        15: 'Rekel mu je: »Oh moj Gospod, s čim bom rešil Izraela? Glej, moja družina je revna v Manáseju in jaz sem najmanjši v očetovi hiši.«',
        16: 'Gospod mu je rekel: »Zagotovo bom jaz s teboj in Midjánce boš udaril kakor en mož.«',
        17: 'Ta mu je rekel: »Če sem torej našel milost v tvojem pogledu, potem mi pokaži znamenje, da ti govoriš z menoj.',
        18: 'Ne odidi od tod, prosim te, dokler ne pridem k tebi in prinesem svoje darilo in ga postavim predte.« Rekel je: »Ostal bom, dokler ponovno ne prideš.«',
        19: 'Gideón je vstopil in pripravil kozlička in nekvašene kolače iz škafa moke. Meso je položil v košaro, juho v lonec in to prinesel ven k njemu pod hrast in to ponudil.',
        20: 'Angel od Boga mu je rekel: »Vzemi meso in nekvašene kolače ter jih položi na to skalo in izlij juho.« In tako je storil.',
        21: 'Potem je Gospodov angel iztegnil konec palice, ki je bila v njegovi roki in se dotaknil mesa in nekvašenih kolačev. In iz skale se je dvignil ogenj in použil meso ter nekvašene kolače. Potem je Gospodov angel odšel iz njegovega pogleda.',
        22: 'Ko je Gideón zaznal, da je bil to Gospodov angel, je Gideón rekel: »Ojoj, oh Gospod Bog! Ker sem videl Gospodovega angela iz obličja v obličje.«',
        23: 'Gospod mu je rekel: »Mir ti bodi, ne boj se. Ne boš umrl.«',
        24: 'Potem je Gideón tam zgradil oltar Gospodu in ga imenoval Jahve–šalom. Do današnjega dne je ta še vedno v Ofri Abiézerjevcev.',
        25: 'Pripetilo se je isto noč, da mu je Gospod rekel: »Vzemi mladega bikca od svojega očeta, celo drugega bikca starosti sedmih let in zruši Báalov oltar, ki ga ima tvoj oče in posekaj ašero, ki je poleg njega',
        26: 'in zgradi oltar Gospodu, svojemu Bogu, na vrhu te skale, na določenem kraju in vzemi drugega bikca in daruj žgalno daritev z lesom ašere, ki jo boš posekal.«',
        27: 'Potem je Gideón vzel deset mož izmed svojih služabnikov in storil, kakor mu je Gospod rekel. Bilo je tako, ker se je bal očetove družine in mož mesta, da tega ni mogel storiti podnevi, da je to storil ponoči.',
        28: 'Ko so možje mesta zgodaj zjutraj vstali, glej, Báalov oltar je bil podrt in ašera, ki je bila poleg njega, je bila posekana in drugi bikec je bil darovan na oltarju, ki je bil zgrajen.',
        29: 'Drug drugemu so rekli: »Kdo je storil to stvar?« Ko so poizvedovali in spraševali, so rekli: »To stvar je storil Joášev sin Gideón.«',
        30: 'Potem so možje iz mesta Joášu rekli: »Privedi svojega sina ven, da bo lahko umrl, ker je podrl Báalov oltar in ker je posekal ašero, ki je bila poleg njega.«',
        31: 'Joáš je rekel vsem, ki so stali zoper njega: »Mar se boste potegovali za Báala? Ali ga boste vi rešili? Kdor se bo potegoval zanj, naj bo usmrčen, medtem ko je še jutro. Če je on bog, naj se poteguje sam zase, ker je nekdo podrl njegov oltar.«',
        32: 'Zato ga je na ta dan imenoval Jerubáal, rekoč: »Naj Báal navaja dokaze zoper njega, ker je zrušil njegov oltar.«',
        33: 'Potem so se skupaj zbrali vsi Midjánci, Amálečani in otroci vzhoda, odšli preko in se utaborili v dolini Jezreél.',
        34: 'Toda Gospodov Duh je prišel nad Gideóna in ta je zatrobil na šofar in Abiézer je bil zbran za njim.',
        35: 'Poslal je poslance po vsem Manáseju, ki je bil tudi zbran za njim. Poslal je poslance k Aserju, k Zábulonu in k Neftáliju in prišli so gor, da jih srečajo.',
        36: 'Gideón je rekel Bogu: »Če hočeš po moji roki rešiti Izraela, kakor si rekel,',
        37: 'glej, bom na tla položil ovčje runo in če bo rosa samo na runu in bo vsa zemlja poleg suha, potem bom vedel, da hočeš po moji roki rešiti Izraela, kakor si rekel.«',
        38: 'In bilo je tako, kajti naslednji dan je zgodaj vstal in iz runa iztisnil roso, polno skledico vode.',
        39: 'Gideón je rekel Bogu: »Tvoja jeza naj se ne vname zoper mene in govoril bom samo še tokrat. Naj dokažem, prosim te, samo še tokrat z runom. Naj bo sedaj suho samo na runu, po vsej zemlji pa naj bo rosa.«',
        40: 'Bog je to noč storil tako, kajti bilo je suho samo na runu, rosa pa je bila po vsej zemlji.',
    },
    7: {
        1: 'Potem je Jerubáal, ki je Gideón in vse ljudstvo, ki je bilo z njim, vstalo zgodaj in se utaborilo poleg vodnjaka Haród, tako da je bila vojska Midjáncev na njihovi severni strani, v dolini pri Moréjevem hribu.',
        2: 'Gospod je rekel Gideónu: »Ljudstva, ki je s teboj, je zame preveč, da bi Midjánce izročil v njihove roke, da se ne bi Izrael poveličeval zoper mene, rekoč: ›Moja lastna roka me je rešila.‹«',
        3: 'Zdaj torej pojdi, razglasi v ušesa ljudstva, rekoč: ›Kdorkoli je boječ in se boji, naj se vrne in zgodaj odide z gore Gileád.‹« In tam se jih je izmed ljudstva vrnilo dvaindvajset tisoč, ostalo pa jih je deset tisoč.',
        4: 'Gospod je rekel Gideónu: »Ljudstva je še preveč. Privedi jih dol k vodi in tam ti jih bom preizkusil.« Zgodilo se bo, da o komer ti rečem: ›Ta bo šel s teboj,‹ bo ta isti šel s teboj; in o komer ti rečem: ›Ta ne bo šel s teboj,‹ ta isti ne bo šel.«',
        5: 'Tako je ljudstvo privedel dol k vodi in Gospod je rekel Gideónu: »Kdorkoli s svojim jezikom sreba vodo, kakor sreba pes, tega boš postavil poleg sebe, podobno vsakega, ki poklekne dol na svoja kolena, da bi pil.«',
        6: 'Število tistih, ki so srebali s pristavljanjem svoje roke k svojim ustom, je bilo tristo mož, toda vsi drugi izmed ljudstva so se upognili na svoja kolena, da pijejo vodo.',
        7: 'Gospod je rekel Gideónu: »S tristo možmi, ki so srebali, vas bom rešil in Midjánce izročil v tvojo roko. Vse preostalo ljudstvo pa naj gre vsak mož k svojemu kraju.«',
        8: 'Tako je ljudstvo v svojo roko vzelo živež in svoje šofarje, ves preostanek Izraela pa je vsakega moža poslal k svojemu šotoru in obdržal tistih tristo mož. Midjánska vojska pa je bila pod njim v dolini.',
        9: 'Iste noči se je pripetilo, da mu je Gospod rekel: »Vstani, spusti se k vojski, kajti izročil sem jo v tvojo roko.',
        10: 'Toda če se bojiš iti dol, pojdi dol k vojski s svojim služabnikom Purájem.',
        11: 'Slišal boš kaj govorijo. Potem se bodo tvoje roke okrepile, da greš dol k vojski.« Potem je s svojim služabnikom Purájem odšel dol k zunanjim izmed oboroženih mož, ki so bili v vojski.',
        12: 'Midjánci in Amalečani in vsi otroci vzhoda pa so ležali povprek po dolini, zaradi množice podobni kobilicam in njihovih kamel je bilo zaradi množice brez števila, kakor peska ob morski obali.',
        13: 'Ko je Gideón prišel, glej, je bil tam mož, ki je svojemu tovarišu povedal sanje ter rekel: »Glej, sanjal sem sanje in glej, kolač ječmenovega kruha se je privalil v midjánsko vojsko, prišel k šotoru in ga udaril, da je ta padel in ga prevrnil, da je ležal postrani.«',
        14: 'Njegov tovariš je odgovoril in rekel: »To ni nič drugega kakor meč Gideóna, Joáševega sina, moža iz Izraela, kajti v njegovo roko je Bog izročil Midjánce in vso vojsko.«',
        15: 'Bilo je tako, ko je Gideón slišal pripovedovanje sanj in njeno razlago, da je oboževal, se vrnil v Izraelovo vojsko in rekel: »Vstanite, kajti Gospod je v vašo roko izročil midjánsko vojsko.«',
        16: 'Tristo mož je razdelil na tri skupine in v roko vsakega moža položil šofar s praznimi lončenimi vrči in svetilkami znotraj vrčev.',
        17: 'Rekel jim je: »Glejte mene in storite podobno. In glejte, ko pridem k robu tabora, se bo zgodilo, da kakor storim jaz, boste tako storili tudi vi.',
        18: 'Ko zatrobim s šofarjem, jaz in vsi tisti, ki so z menoj, potem tudi vi zatrobite s šofarji na vsaki strani tabora in recite: › Meč od Gospoda in od Gideóna.‹«',
        19: 'Tako so Gideón in sto mož, ki so bili z njim, prišli k robu tabora na začetku srednje straže in imeli so ravno sveže postavljeno stražo. Zatrobili so na šofarje in razbili lončene vrče, ki so bili v njihovih rokah.',
        20: 'Tri skupine so trobile na šofarje in razbile lončene vrče in držale svetilke v svojih levicah in šofarje v svojih desnicah, da z njimi trobijo in kričali: »Meč od Gospoda in od Gideóna.«',
        21: 'Stali so vsak mož na svojem mestu okoli tabora in vsa vojska je stekla, kričala in pobegnila.',
        22: 'Tristo [jih] je trobilo na šofarje in Gospod je torej po vsej vojski naravnal meč vsakega moža zoper svojega tovariša in vojska je pobegnila do Bet Šite v Cerédi in do meje Abél Mehóle, do Tabáta.',
        23: 'Izraelovi možje so se zbrali skupaj iz Neftálija, iz Aserja, iz vsega Manáseja in zasledovali Midjánce.',
        24: 'Gideón je poslal poslance po vsej gori Efrájim, rekoč: »Pridite dol zoper Midjánce in pred njimi zasedite vode do Bet Bare in Jordana.« Potem so se vsi Efrájimovi možje zbrali skupaj in zasedli vode do Bet Bare in Jordana.',
        25: 'Zajeli so dva princa izmed Midjáncev, Oréba in Zeéba. Oréba so usmrtili na Orébovi skali, Zeéba pa so usmrtili na Zeébovi vinski stiskalnici in zasledovali Midjánce ter glavi Oréba in Zeéba prinesli Gideónu, na drugo stran Jordana.',
    },
    8: {
        1: 'Možje iz Efrájima so mu rekli: »Zakaj si nam tako služil, da nas nisi poklical, ko si odhajal, da bi se bojeval z Midjánci?« In ostro so se pričkali z njim.',
        2: 'Rekel jim je: »Kaj sem torej storil v primerjavi z vami? Mar ni Efrájimovo paberkovanje boljše kakor Abiézerjeva trgatev?',
        3: 'Bog je v vaše roke izročil midjánska princa, Oréba in Zeéba. Kaj sem bil jaz zmožen storiti v primerjavi z vami?« Potem ko jim je to rekel, se je njihova jeza zoper njega zmanjšala.',
        4: 'Gideón je prišel do Jordana ter ga prečkal, on in tristo mož, ki so bili z njim, slabotni, vendar so jih zasledovali.',
        5: 'Možem iz Sukóta je rekel: »Dajte, prosim vas, hlebe kruha ljudstvu, ki mi sledi, kajti oslabeli so in jaz zasledujem midjánska kralja Zebaha in Calmunája.«',
        6: 'Princi iz Sukóta so rekli: » Mar so roke Zebaha in Calmunája sedaj v tvoji roki, da bi tvoji vojski dali kruha?«',
        7: 'Gideón je rekel: »Torej ko Gospod Zebaha in Calmunája izroči v mojo roko, potem bom vaše meso raztrgal s trnjem iz divjine in z osatom.«',
        8: 'Od tam je odšel gor do Penuéla in jim podobno govoril. Ljudje iz Penuéla so mu odgovorili podobno kot ljudje iz Sukóta.',
        9: 'Govoril je tudi ljudem iz Penuéla, rekoč: »Ko ponovno pridem v miru, bom porušil ta stolp.«',
        10: 'Torej Zebah in Calmunáj sta bila v Karkórju in njune vojske z njima, okoli petnajst tisoč mož, vsi, ki so preostali od vseh vojsk otrok vzhoda, kajti tam je padlo sto dvajset tisoč mož, ki so izdirali meč.',
        11: 'Gideón je odšel gor po poti tistih, ki so prebivali v šotorih vzhodno od Nobaha in Jogbóhe in udaril vojsko, kajti vojska je bila brezskrbna.',
        12: 'Ko sta Zebah in Calmunáj pobegnila, ju je zasledoval in zajel dva midjánska kralja, Zebaha in Calmunája ter porazil vso vojsko.',
        13: 'Joášev sin Gideón se je vrnil iz bitke, preden je vzšlo sonce.',
        14: 'Ujel je mladeniča izmed ljudi iz Sukóta in od njega poizvedel in ta mu je opisal prince iz Sukóta in njihove starešine, celó sedeminsedemdeset mož.',
        15: 'Prišel je k možem iz Sukóta in rekel: »Glejte Zebaha in Calmunája, s katerima ste me ošteli, rekoč: ›Mar so roke Zebaha in Calmunája sedaj v tvoji roki, da naj bi dali kruha tvojim možem, ki so izmučeni.‹«',
        16: 'Zgrabil je mestne starešine in trnje iz divjine in osat ter z njimi učil može iz Sukóta.',
        17: 'Podrl je stolp v Penuélu in usmrtil može iz mesta.',
        18: 'Potem je Zebahu in Calmunáju rekel: »Kakšne vrste možje so bili tisti, ki sta jih usmrtila pri Taboru?« Odgovorila sta: »Takšni so bili, kot si ti. Vsakdo je bil podoben kraljevemu otroku.«',
        19: 'Rekel je: » Bili so moji bratje, celó sinovi moje matere. Kakor živi Gospod, če bi jih rešila žive, vaju ne bi ubil.«',
        20: 'Svojemu prvorojencu Jeterju je rekel: »Vstani in ju ubij.« Toda mladostnik ni izvlekel svojega meča, kajti bal se je, ker je bil še mladostnik.',
        21: 'Potem sta Zebah in Calmunáj rekla: »Vstani ti in padi na naju, kajti kakršen je mož, takšna je njegova moč.« Gideón je vstal in usmrtil Zebaha in Calmunája in odvzel ornamente, ki so bili na vratovih njunih kamel.',
        22: 'Potem so možje iz Izraela rekli Gideónu: »Ti vladaj nad nami, oba, ti in tvoj sin in tudi sin tvojega sina, kajti osvobodil si nas iz roke Midjáncev.«',
        23: 'Gideón jim je rekel: »Jaz ne bom vladal nad vami niti ne bo moj sin vladal nad vami. Gospod bo vladal nad vami.«',
        24: 'Gideón jim je rekel: »Od vas bi želel prošnjo, da bi mi dal vsak mož uhane od svojega plena.« (Kajti imeli so zlate uhane, ker so bili Izmaelci.)',
        25: 'Odgovorili so: »Voljno jih bomo dali.« Razširili so obleko in nanjo je vsak mož vrgel uhane od svojega plena.',
        26: 'Teža zlatih uhanov, ki jih je zahteval, je bila tisoč sedemsto šeklov zlata, poleg ornamentov in obeskov za ušesa in škrlatnega oblačila, ki je bil na midjánskih kraljih in poleg verižic, ki so bile okoli vratov njihovih kamel.',
        27: 'Gideón je iz njih naredil efód in ga dal v svoje mesto, v Ofro. Ves Izrael se je odšel tja vlačugat za njim. Ta stvar je postala zanka Gideónu in njegovi hiši.',
        28: 'Tako je bil Midján podjarmljen pred Izraelovimi otroki, tako da niso več vzdignili svojih glav. In dežela je bila v Gideónovih dneh v spokojnosti štirideset let.',
        29: 'Joášev sin Jerubáal je odšel in prebival v svoji lastni hiši.',
        30: 'Gideón je imel sedemdeset sinov, rojenih od njegovega telesa, kajti imel je mnogo žena.',
        31: 'Njegova priležnica, ki je bila v Sihemu, mu je prav tako rodila sina, čigar ime je imenoval Abiméleh.',
        32: 'Joášev sin Gideón je umrl v dobri visoki starosti in bil pokopan v mavzoleju njegovega očeta Joáša v Ofri Abiézerjevcev.',
        33: 'Takoj, ko je bil Gideón mrtev, se je pripetilo, da so se Izraelovi otroci ponovno obrnili in se šli vlačugat za Báali in si naredili Baal-berita za svojega boga.',
        34: 'Izraelovi otroci se niso spominjali Gospoda, svojega Boga, ki jih je osvobodil iz rok vseh njihovih sovražnikov na vsaki strani',
        35: 'niti niso izkazali prijaznosti Jerubáalovi hiši, namreč Gideónu, glede na vso dobroto, ki jo je izkazal Izraelu.',
    },
    9: {
        1: 'Jerubáalov sin Abiméleh je šel do Sihema, do bratov svoje matere in se z njimi posvetoval in z vso družino hiše očeta svoje matere, rekoč:',
        2: '»Govorite, prosim vas, na ušesa vsem sihemskim gospodarjem: ›Ali je za vas bolje, da vsi Jerubáalovi sinovi, katerih je sedemdeset oseb, kraljujejo nad vami ali da nad vami kraljuje eden? Spomnite se tudi, da sem jaz vaša kost in vaše meso.‹«',
        3: 'Bratje njegove matere so vse te besede o njem govorili v ušesa vseh sihemskih gospodarjev in njihova srca nagnili, da sledijo Abimélehu, kajti rekli so: »On je naš brat.«',
        4: 'Iz hiše Baal-berita so mu dali sedemdeset koščkov srebra, s katerimi je Abiméleh najel prazno-glave in nepomembne osebe, ki so mu sledili.',
        5: 'Odšel je v hišo svojega očeta pri Ofri in na enem kamnu usmrtil svoje brate, Jerubáalove sinove, ki jih je bilo sedemdeset oseb. Kljub temu pa je ostal najmlajši Jerubáalov sin Jotám, kajti ta se je skril.',
        6: 'Vsi sihemski gospodarji so se zbrali skupaj in vsa Milójeva hiša in odšli ter Abiméleha postavili za kralja pri ravninskem stebru, ki je bil v Sihemu.',
        7: 'Ko so to povedali Jotámu, je ta odšel in se postavil na vrhu gore Garizím, povzdignil svoj glas, zavpil in jim rekel: »Prisluhnite mi, vi sihemski gospodarji, da bo Bog lahko prisluhnil vam.',
        8: 'Drevesa so šla naprej ob času, da mazilijo kralja nad seboj in rekla so oljki: ›Kraljuj nad nami.‹',
        9: 'Toda oljka jim je rekla: ›Mar naj zapustim svojo mastnost, s katero po meni častijo Boga in človeka in grem, da bi bila povišana nad drevesa?‹',
        10: 'Drevesa so rekla figovemu drevesu: ›Ti pridi in kraljuj nad nami.‹',
        11: 'Toda figovo drevo jim je reklo: ›Mar naj zapustim svojo sladkost in svoj dober sad in grem, da bi bilo povišano nad drevesa?‹',
        12: 'Potem so drevesa rekla trti: ›Ti pridi in kraljuj nad nami.‹',
        13: 'Trta pa jim je rekla: ›Mar naj zapustim svoje vino, ki razveseljuje Boga in človeka in grem, da naj bi bila povišana nad drevesa?‹',
        14: 'Potem so vsa drevesa rekla trnovemu grmu: ›Ti pridi in kraljuj nad nami.‹',
        15: 'Trnov grm je rekel drevesom: ›Če me resnično mazilite za kralja nad seboj, potem pridite in svoje zaupanje položite v mojo senco, in če ne, naj ogenj pride iz trnovega grma in použije libanonske cedre.‹',
        16: 'Zdaj torej, če ste storili resnično in iskreno v tem, da ste si postavili Abiméleha za kralja in če ste dobro postopali z Jerubáalom in njegovo hišo in mu storili glede na ravnanje njegovih rok',
        17: '(kajti moj oče se je bojeval za vas in v ospredju tvegal svoje življenje in vas osvobodil iz roke Midjáncev',
        18: 'in ste ta dan vstali zoper hišo mojega očeta in umorili njegove sinove, sedemdeset oseb na enem kamnu in postavili Abiméleha, sina njegove dekle, za kralja nad sihemskimi gospodarji, ker je vaš brat).',
        19: 'Če ste torej ta dan resnično in iskreno postopali z Jerubáalom in njegovo hišo, potem se veselite z Abimélehom in naj se tudi on veseli z vami.',
        20: 'Toda če ne, naj ogenj pride od Abiméleha in pogoltne sihemske gospodarje in Milójevo hišo. In ogenj naj pride od sihemskih gospodarjev in od Milójeve hiše in požre Abiméleha.',
        21: 'Jotám je stekel proč, pobegnil in odšel v Beêr in tam prebival zaradi strahu pred svojim bratom Abimélehom.',
        22: 'Ko je Abiméleh tri leta kraljeval nad Izraelom,',
        23: 'je potem Bog med Abiméleha in sihemske gospodarje poslal zlega duha in sihemski gospodarji so zahrbtno postopali z Abimélehom,',
        24: 'da bi ta krutost, storjena sedemdesetim Jerubáalovim sinovom lahko prišla in bi bila njihova kri položena na njihovega brata Abiméleha, ki jih je umoril in na sihemske gospodarje, ki so mu pomagali pri morjenju njegovih bratov.',
        25: 'Sihemski gospodarji so zanj postavili prežavce v zasedi na vrhu gora in ti so oropali vse, ki so mimo njih prišli po tej poti, in to je bilo povedano Abimélehu.',
        26: 'Ebedov sin Gáal je prišel s svojimi brati in odšel preko v Sihem in sihemski gospodarji so svoje zaupanje položili vanj.',
        27: 'Odšli so ven na polja in obrali svoje vinograde in tlačili grozdje in se veselili in odšli v hišo svojega boga, jedli, pili in preklinjali Abiméleha.',
        28: 'Ebedov sin Gáal je rekel: »Kdo je Abiméleh in kdo je Sihem, da bi mu služili? Mar ni on Jerubáalov sin? In Zebúl njegov častnik? Služite možem Sihemovega očeta Hamórja, kajti zakaj bi mi služili njemu?',
        29: 'Bog daj, da bi bilo to ljudstvo pod mojo roko! Potem bi odstranil Abiméleha.« In Abimélehu je rekel: »Okrepi svojo vojsko in pridi ven.«',
        30: 'Ko je Zebúl, vladar mesta, slišal besede Ebedovega sina Gáala, je bila njegova jeza vžgana.',
        31: 'Na skrivnem je poslal poslance k Abimélehu, rekoč: »Glej, Ebedov sin Gáal in njegovi bratje so prišli v Sihem in glej, zoper tebe utrjujejo mesto.',
        32: 'Zdaj se torej dvigni ponoči ti in ljudstvo, ki je s teboj in na polju prežite v zasedi',
        33: 'in zgodilo se bo, da zjutraj, takoj ko bo sonce vzšlo, da boš zgodaj vstal in se nameril na mesto. In glej, ko bodo on in ljudstvo, ki je z njim, prišli ven zoper tebe, potem jim boš lahko storil kakor boš našel priložnost.«',
        34: 'Abiméleh je ponoči vstal in vse ljudstvo, ki je bilo z njim in so v štirih skupinah prežali zoper Sihem.',
        35: 'Ebedov sin Gáal je odšel ven in stal v vhodu velikih vrat mesta. Abiméleh in ljudstvo, ki je bilo z njim, pa je vstalo od prežanja.',
        36: 'Ko je Gáal zagledal ljudstvo, je rekel Zebúlu: »Glej, tam prihaja ljudstvo dol iz vrha gorovja.« Zebúl mu je rekel: »Senco gorovja vidiš, kakor bi bili možje.«',
        37: 'Gáal je ponovno spregovoril in rekel: »Vidiš, tam prihaja dol ljudstvo po sredi dežele in druga skupina prihaja vzdolž ravnine Maonim.«',
        38: 'Potem mu je Zebúl rekel: »Kje so sedaj tvoja usta, s katerimi praviš: ›Kdo je Abiméleh, da bi mu služili?‹ Mar ni to ljudstvo, ki si ga preziral? Pojdi sedaj ven, prosim te in se bori z njimi.«',
        39: 'Gáal je odšel ven pred sihemskimi gospodarji in se boril z Abimélehom.',
        40: 'Abiméleh ga je pregnal in ta je pobegnil pred njim in mnogi so bili zrušeni in ranjeni, celó do vhoda velikih vrat.',
        41: 'Abiméleh je prebival pri Arúmi, Zebúl pa je vrgel ven Gáala in njegove brate, da ne bi prebivali v Sihemu.',
        42: 'Naslednji dan se je pripetilo, da je ljudstvo odšlo ven na polje in povedali so Abimélehu.',
        43: 'Ta je vzel ljudstvo in jih razdelil v tri skupine. Na polju so prežali v zasedi in glej, ljudstvo je prišlo ven iz mesta. Vstal je zoper njih in jih udaril.',
        44: 'Abiméleh in skupina, ki je bila z njim, je pohitela naprej in stala na vhodu velikih vrat mesta in dve drugi skupini sta stekli nad vse ljudstvo, ki je bilo na poljih in jih usmrtili.',
        45: 'Abiméleh se je ves tisti dan boril zoper mesto, zavzel mesto, usmrtil ljudstvo, ki je bilo v njem, premagal mesto in ga potresel s soljo.',
        46: '§ Ko so vsi gospodarji sihemskega stolpa to slišali, so vstopili v trdnjavo hiše boga Berita.',
        47: 'To je bilo povedano Abimélehu, da so bili vsi gospodarji sihemskega stolpa zbrani skupaj.',
        48: 'Abiméleh se je povzpel na goro Calmón, on in vse ljudstvo, ki je bilo z njim in Abiméleh je v svojo roko vzel sekiro, odsekal vejo iz dreves, jo vzel in jo položil na svojo ramo in rekel ljudstvu, ki je bilo z njim: »Kar ste videli storiti mene, pohitite in storite, kakor sem storil jaz.«',
        49: 'Podobno je vse ljudstvo odsekalo vsak svojo vejo, sledilo Abimélehu, jih položili k trdnjavi in zažgali trdnjavo nad njimi. Tako da so umrli tudi vsi ljudje iz sihemskega stolpa, okoli tisoč mož in žena.',
        50: 'Potem je Abiméleh odšel v Tebéc, se utaboril zoper Tebéc in ga zavzel.',
        51: 'Toda tam, znotraj mesta, je bil močan stolp in tja so pobegnili vsi možje in žene in vsi iz mesta in ga za seboj zaprli in se spravili na vrh stolpa.',
        52: 'Abiméleh je prišel k stolpu, se boril zoper njega in se približal vratom stolpa, da bi ga zažgal z ognjem.',
        53: 'Neka ženska je kos mlinskega kamna vrgla na Abimélehovo glavo in razbila njegovo lobanjo.',
        54: 'Potem je naglo zaklical k mladeniču, svojemu nosilcu bojne opreme in mu rekel: »Izvleci svoj meč in me usmrti, da ne bodo ljudje o meni rekli: ›Ubila ga je ženska.‹« In njegov mladenič ga je prebodel in ta je umrl.',
        55: 'Ko so možje iz Izraela videli, da je bil Abiméleh mrtev, so odšli vsak mož na svoj kraj.',
        56: 'Tako je Bog povrnil Abimélehovo zlobnost, ki jo je storil svojemu očetu z umorom svojih sedemdesetih bratov',
        57: 'in vse zlo sihemskih ljudi je Bog povrnil na njihove glave in nadnje je prišlo prekletstvo Jerubáalovega sina Jotáma.',
    },
    10: {
        1: 'Za Abimélehom je vstal Tolá, sin Puvája, sinú Dodója, mož iz Isahárja, da brani Izrael. Prebival je v Šamíru, na gori Efrájim.',
        2: 'Izraelu je sodil triindvajset let in umrl ter bil pokopan v Šamíru.',
        3: 'Za njim je vstal Gileádec Jaír in Izraelu sodil dvaindvajset let.',
        4: 'Imel je trideset sinov, ki so jahali na tridesetih osličjih žrebetih in imeli so trideset mest, ki se imenujejo Havot Jaír do tega dne, ki so v deželi Gileád.',
        5: 'Jaír je umrl in bil pokopan v Kamónu.',
        6: 'Izraelovi otroci pa so v Gospodovih očeh ponovno počeli zlo in služili Báalom, Astarti, bogovom Sirije, bogovom Sidóna, bogovom Moába, bogovom Amónovih otrok in bogovom Filistejcev in zapustili so Gospoda in mu niso služili.',
        7: 'Gospodova jeza je bila vroča zoper Izrael in prodal jih je v roke Filistejcev in v roke Amónovih otrok.',
        8: 'Tisto leto so tlačili in zatirali Izraelove otroke; osemnajst let, vse Izraelove otroke, ki so bili na drugi strani Jordana, v deželi Amoréjcev, ki je v Gileádu.',
        9: 'Poleg tega so Amónovi otroci prečkali Jordan, da se borijo tudi zoper Juda, zoper Benjamina in zoper Efrájimovo hišo, tako, da je bil Izrael silno stiskan.',
        10: 'Izraelovi otroci so vpili h Gospodu, rekoč: »Grešili smo zoper tebe, zato ker smo zapustili svojega Boga in služili tudi Báalom.«',
        11: 'Gospod je Izraelovim otrokom rekel: » Mar vas nisem osvobodil pred Egipčani in pred Amoréjci, pred Amónovimi otroki in pred Filistejci?',
        12: 'Tudi Sidónci, Amalečani in Maonci so vas zatirali in klicali ste k meni in osvobodil sem vas iz njihove roke.',
        13: 'Vendar ste me zapustili in služili drugim bogovom, zato vas ne bom več osvobajal.',
        14: 'Pojdite in jokajte k bogovom, ki ste jih izbrali. Naj vas oni osvobodijo v času vaše stiske.«',
        15: 'Izraelovi otroci so rekli Gospodu: »Grešili smo. Stôri nam, karkoli se ti zdi dobro. Prosimo te, samo osvobodi nas ta dan.«',
        16: 'Izmed sebe so odstranili tuje bogove in služili Gospodu. Njegova duša je bila užaloščena zaradi Izraelove bede.',
        17: 'Potem so bili Amónovi otroci zbrani skupaj in se utaborili v Gileádu. Izraelovi otroci pa so se zbrali skupaj in se utaborili v Micpi.',
        18: 'Ljudstvo in gileádski princi so drug drugemu rekli: »Kateri mož je ta, ki se bo začel boriti zoper Amónove otroke? Ta bo poglavar nad vsemi prebivalci Gileáda.«',
    },
    11: {
        1: 'Torej Gileádec Jefte je bil mogočen hraber človek in bil je sin pocestnice; in Gileád je zaplodil Jefteja.',
        2: 'Gileádova žena mu je rodila sinove in sinovi njegove žene so zrasli in pregnali Jefteja ter mu rekli: »Ne boš dedoval v hiši našega očeta, kajti ti si sin tuje ženske.«',
        3: 'Potem je Jefte pobegnil pred svojimi brati in prebival v deželi Tob. Tam pa so bili k Jefteju zbrani praznoglavi možje in z njim odšli ven.',
        4: 'In pripetilo se je tekom časa, da so Amónovi otroci začeli vojno zoper Izrael.',
        5: 'Bilo je tako, da ko so Amónovi otroci začeli vojno zoper Izrael, so starešine iz Gileáda odšli, da Jefteja pripeljejo iz dežele Tob.',
        6: 'Jefteju so rekli: »Pridi in bodi naš poveljnik, da se bomo lahko borili z Amónovimi otroki.«',
        7: 'Jefte je rekel starešinam iz Gileáda: »Ali me niste sovražili in pregnali iz hiše mojega očeta? Zakaj ste prišli k meni sedaj, ko ste v stiski?«',
        8: 'Starešine iz Gileáda so Jefteju rekli: »Zato se sedaj ponovno obračamo k tebi, da boš lahko šel z nami in se boril zoper Amónove otroke in boš naš poglavar nad vsemi prebivalci Gileáda.«',
        9: 'Jefte je rekel starešinam iz Gileáda: »Če me ponovno privedete domov, da se borim zoper Amónove otroke in jih Gospod izroči pred menoj, ali bom vaš poglavar?«',
        10: 'Starešine iz Gileáda so rekli Jefteju: » Gospod bodi priča med nami, če ne storimo tako glede na tvoje besede.«',
        11: 'Potem je Jefte odšel s starešinami iz Gileáda in ljudstvo ga je postavilo za poglavarja in poveljnika nad njimi in Jefte je vse svoje besede izrekel pred Gospodom v Micpi.',
        12: 'Jefte je poslal poslance h kralju Amónovih otrok, rekoč: »Kaj imaš z menoj, da si prišel zoper mene, da se boriš v moji deželi?«',
        13: 'Kralj Amónovih otrok je Jeftejevim poslancem odgovoril: »Ker je Izrael odvzel mojo deželo, ko so prišli gor iz Egipta, od Arnóna, celo do Jabóka in do Jordana. Sedaj torej ponovno miroljubno povrni te dežele.«',
        14: 'Jefte je ponovno poslal poslance h kralju Amónovih otrok',
        15: 'in mu rekel: »Tako govori Jefte: ›Izrael ni odvzel moábske dežele niti dežele Amónovih otrok,',
        16: 'temveč ko je Izrael prišel gor iz Egipta in skozi divjino hodil do Rdečega morja in prišel do Kadeša,',
        17: 'potem je Izrael poslal poslance k edómskemu kralju, rekoč: ›Pusti mi, prosim te, iti skozi tvojo deželo.‹ Toda edómski kralj temu ni hotel prisluhniti. In na podoben način so poslali k moábskemu kralju. Toda ta ni hotel privoliti in Izrael je ostal v Kadešu.',
        18: 'Potem so šli vzdolž skozi divjino in obkrožili edómsko deželo in moábsko deželo in prišli pri vzhodni strani moábske dežele in se utaborili na drugi strani Arnóna, toda niso prišli znotraj moábske meje, kajti Arnón je bil moábska meja.',
        19: 'Izrael je poslal poslance k Sihónu, kralju Amoréjcev, hešbónskemu kralju. Izrael mu je rekel: ›Naj gremo, prosim te, skozi tvojo deželo na svoj kraj.‹',
        20: 'Toda Sihón ni zaupal Izraelu, da gre skozi njegovo pokrajino, temveč je Sihón zbral skupaj vse svoje ljudstvo, se utaboril v Jahacu in se boril zoper Izrael.',
        21: 'Gospod, Izraelov Bog, je Sihóna in vse njegovo ljudstvo izročil v roko Izraelcev in ti so jih udarili. Tako je Izrael vzel v last vso deželo Amoréjcev, prebivalcev tiste dežele.',
        22: 'V last so vzeli vse pokrajine Amoréjcev, od Arnóna, celo do Jabóka in od divjine, celo do Jordana.',
        23: 'Tako je torej Gospod, Izraelov Bog, Amoréjce razlastil izpred svojega ljudstva Izraela in ti naj bi to vzel v last?',
        24: 'Ali ne boš vzel v last tega, kar ti tvoj bog Kemoš daje v last? Tako kogarkoli bo Gospod, naš Bog, napodil izpred nas, te bomo vzeli v last.',
        25: 'In sedaj ali si ti kakorkoli boljši kakor Balák, Cipórjev sin, moábski kralj? Ali se je on kdaj prepiral zoper Izrael, ali se je kdaj boril zoper njih,',
        26: 'medtem ko je Izrael tristo let prebival v Hešbónu in njegovih mestih, v Aroêrju in njegovih mestih in v vseh mestih, ki so vzdolž ob pokrajinah Arnóna? Zakaj jih torej niste povrnili znotraj tega časa?',
        27: 'Zato nisem grešil zoper tebe, temveč mi ti delaš krivico, da se vojskuješ zoper mene. Gospod, Sodnik, naj bo danes sodnik med Izraelovi otroci in Amónovimi otroci.‹«',
        28: 'Vendar kralj Amónovih otrok ni prisluhnil Jeftejevim besedam, ki mu jih je poslal.',
        29: 'Potem je Gospodov Duh prišel nad Jefteja in ta je prečkal Gileád in Manáse in šel čez Micpo v Gileádu in iz Micpe v Gileádu prečkal k Amónovim otrokom.',
        30: 'Jefte je prisegel zaobljubo Gospodu in rekel: »Če mi boš čisto gotovo izročil Amónove sinove v moje roke,',
        31: 'potem se bo zgodilo, da kdorkoli pride naprej od vrat moje hiše, da bi me srečal, ko se v miru vrnem od Amónovih otrok, bo zagotovo Gospodov in daroval ga bom za žgalno daritev.«',
        32: 'Tako je Jefte prešel preko k Amónovim otrokom, da se bori zoper njih in Gospod jih je izročil v njegove roke.',
        33: 'Udaril jih je od Aroêrja, celo dokler ne prideš v Minít, celó dvajset mest in do ravnine vinogradov, z zelo velikim pokolom. Tako so bili Amónovi otroci podjarmljeni pred Izraelovimi otroci.',
        34: 'Jefte je prišel v Micpo, k svoji hiši in glej, njegova hči je prišla ven, da ga sreča s tamburini in s plesi. Ona pa je bila njegov edini otrok. Poleg nje ni imel niti sina niti hčere.',
        35: 'Pripetilo se je, ko jo je zagledal, da je pretrgal svoja oblačila in rekel: »Ojoj, moja hči! Zelo si me potrla in ti si ena izmed tistih, ki me vznemirjajo, kajti svoja usta sem odprl h Gospodu in se ne morem obrniti nazaj.«',
        36: 'Rekla mu je: »Moj oče, če si svoja usta odprl h Gospodu, mi stori glede na to, kar je prišlo iz tvojih ust, kakor se je Gospod zate maščeval na tvojih sovražnikih, na Amónovih otrocih.«',
        37: 'Svojemu očetu je rekla: »Naj mi bo storjena ta stvar. Dva meseca me pusti samo, da lahko grem gor in dol po gorah in objokujem svoje devištvo, jaz in moje prijateljice.«',
        38: 'Rekel je: »Pojdi.« In za dva meseca jo je poslal proč in odšla je s svojimi družabnicami ter po gorah objokovala svoje devištvo.',
        39: 'Pripetilo se je ob koncu dveh mesecev, da se je vrnila k svojemu očetu, ki je z njo storil glede na svojo zaobljubo, ki jo je prisegel. Nobenega moškega ni spoznala. In to je bil zakon v Izraelu,',
        40: 'da so Izraelove hčere vsako leto odšle, da štiri dni v letu objokujejo hčer Gileádca Jefteja.',
    },
    12: {
        1: 'Možje iz Efrájima so se zbrali skupaj in odšli proti severu in rekli Jefteju: »Zakaj prehajaš preko, da se boriš zoper Amónove otroke, nas pa nisi poklical, da gremo s teboj? Nad teboj bomo tvojo hišo požgali z ognjem.«',
        2: 'Jefte jim je rekel: »Jaz in moje ljudstvo smo bili v velikem boju z Amónovimi otroki in ko sem vas poklical, me niste osvobodili iz njihovih rok.',
        3: 'Ko sem videl, da me niste osvobodili, sem svoje življenje vzel v svoje roke in šel preko, proti Amónovim otrokom in Gospod jih je izročil v mojo roko. Zakaj ste torej vi ta dan prišli gor do mene, da se borite zoper mene?«',
        4: 'Potem je Jefte zbral skupaj vse gileádske može in se bojeval z Efrájimom in gileádski možje so udarili Efrájim, ker so rekli: »Vi Gileádčani ste ubežniki iz Efrájima med Efrájimci in Manásejci.«',
        5: 'Gileádčani so pred Efrájimci zavzeli jordanske prehode. In bilo je tako, da ko so tisti Efrájimci, ki so pobegnili, rekli: »Naj grem preko,« da so mu gileádski možje rekli: » Ali si Efrájimec?« Če je rekel: »Ne,«',
        6: 'potem so mu rekli: »Reci sedaj Šibólet« in je rekel »Sibólet,« kajti tega ni mogel pravilno naglasiti. Potem so ga prijeli in usmrtil pri jordanskih prehodih in tam jih je ob tistem času izmed Efrájimcev padlo dvainštirideset tisoč.',
        7: 'Jefte je Izraelu sodil šest let. Potem je Gileádčan Jefte umrl in bil pokopan v enem izmed mest Gileáda.',
        8: 'Za njim je Izraelu sodil Ibcán iz Betlehema.',
        9: 'Ta je imel trideset sinov in trideset hčera, ki jih je poslal naokrog in za svoje sinove je vzel trideset hčera od drugod. Izraelu je sodil sedem let.',
        10: 'Potem je Ibcán umrl in je bil pokopan pri Betlehemu.',
        11: 'Za njim je Izraelu sodil Zábulonec Elón. Izraelu je sodil deset let.',
        12: 'Zábulonec Elón je umrl in je bil pokopan v Ajalónu, v deželi Zábulon.',
        13: 'Za njim je Izraelu sodil Abdón, sin Piratónca Hiléla.',
        14: 'Ta je imel štirideset sinov in trideset nečakov, ki so jahali na sedemdesetih osličjih žrebetih. Izraelu je sodil osem let.',
        15: 'Abdón, sin Piratónca Hiléla, je umrl in je bil pokopan v Piratónu, v deželi Efrájim, na gori Amalečanov.',
    },
    13: {
        1: 'Izraelovi otroci so ponovno počeli zlo v Gospodovih očeh in Gospod jih je za štirideset let izročil v roko Filistejcev.',
        2: 'Tam pa je bil nek mož iz Core, iz družine Danovcev, katerega ime je bilo Manóah. Njegova žena pa je bila jalova in ni rodila.',
        3: 'Gospodov angel se je prikazal ženski in ji rekel: »Glej torej, jalova si in ne rojevaš, toda spočela boš in rodila sina.',
        4: 'Zdaj se torej pazi, prosim te in ne pij ne vina ne močne pijače in ne jej nobene nečiste stvari,',
        5: 'kajti glej, spočela boš in rodila sina in nobena britev ne bo prišla na njegovo glavo, kajti otrok bo od maternice nazirec Bogu in on bo začel Izraela osvobajati iz roke Filistejcev.«',
        6: 'Potem je ženska prišla in svojemu soprogu povedala, rekoč: »Božji mož je prišel k meni in njegovo obličje je bilo podobno obličju Božjega angela, zelo strašno. Toda nisem ga vprašala, od kje je bil niti mi ni povedal svojega imena,',
        7: 'toda rekel mi je: ›Glej, spočela boš in rodila sina. Sedaj ne pij ne vina niti močne pijače, tudi ne jej nobene nečiste stvari, kajti otrok bo od maternice nazirec Bogu do dneva svoje smrti.‹«',
        8: 'Potem je Manóah rotil Gospoda in rekel: »Oh moj Gospod, naj Božji mož, ki si ga poslal, ponovno pride k nama in naju pouči, kaj bova storila otroku, ki bo rojen.«',
        9: 'Bog je prisluhnil Manóahovemu glasu in Božji angel je ponovno prišel k ženski, medtem ko je sedela na polju, toda njen soprog Manóah ni bil z njo.',
        10: 'Ženska je pohitela, stekla in pokazala svojemu soprogu ter mu rekla: »Glej, mož se mi je prikazal, ki je prišel k meni oni dan.«',
        11: 'Manóah je vstal in odšel za svojo ženo in prišel k možu ter mu rekel: » Ali si ti mož, ki govoriš ženski?« Rekel je: »Jaz sem.«',
        12: 'Manóah je rekel: »Sedaj naj se tvoje besede zgodijo. Kako naj določiva otroku in kako mu bova storila?«',
        13: 'Gospodov angel je Manóahu rekel: »Pred vsem, kar sem rekel ženski, naj se ona pazi.',
        14: 'Ne sme jesti nobene stvari, ki prihaja od vina, niti naj ne pije vina ali močne pijače, niti naj ne jé nobene nečiste stvari; vsega, kar sem ji zapovedal, naj se drži.«',
        15: 'Manóah je rekel Gospodovemu angelu: »Prosim te, naj te zadrživa, dokler zate ne bova pripravila kozlička.«',
        16: 'Gospodov angel je Manóahu rekel: »Čeprav me zadržiš, ne bom jedel od vajinega kruha. Če pa hočeš darovati žgalno daritev, jo moraš darovati Gospodu.« Kajti Manóah ni vedel, da je bil to Gospodov angel.',
        17: 'Manóah je Gospodovemu angelu rekel: »Kakšno je tvoje ime, potem ko se izpolnijo tvoje besede, da ti lahko izkaževa čast?«',
        18: 'Gospodov angel mu je rekel: »Zakaj sprašuješ po mojem imenu, glede na to, da je to skrivnost?«',
        19: 'Tako je Manóah vzel kozliča z jedilno daritvijo in ga na skali daroval Gospodu in angel je čudežno storil in Manóah in njegova žena sta to videla.',
        20: 'Kajti pripetilo se je, ko se je plamen iz oltarja povzpel proti nebu, da se je Gospodov angel dvignil v oltarnem plamenu. Manóah in njegova žena sta pogledala na to in padla na svoja obraza k tlom.',
        21: 'Toda Gospodov angel se ni več prikazal Manóahu in njegovi ženi. Potem je Manóah vedel, da je bil to Gospodov angel.',
        22: 'Manóah je svoji ženi rekel: »Midva bova zagotovo umrla, ker sva videla Boga.«',
        23: 'Toda njegova žena mu je rekla: »Če bi Gospodu ugajalo, da naju ubije, ne bi pri najinih rokah sprejel žgalne daritve in jedilne daritve, niti nama ne bi pokazal vseh teh stvari, niti nama ob tem času ne bi povedal takšnih stvari, kot so te.«',
        24: 'Ženska je rodila sina in njegovo ime imenovala Samson. In otrok je rastel in Gospod ga je blagoslovil.',
        25: 'In Gospodov Duh ga je občasno začel spodbujati v Danovem taboru, med Coro in Eštaólom.',
    },
    14: {
        1: 'Samson je odšel dol v Timno in v Timni zagledal žensko izmed filistejskih hčera.',
        2: 'Prišel je gor in svojemu očetu in svoji materi povedal ter rekel: »V Timni sem videl žensko izmed filistejskih hčera. Sedaj mi jo torej vzemita za ženo.«',
        3: 'Potem sta mu njegov oče in njegova mati rekla: » Ali tam ni nobene ženske med hčerami tvojih bratov ali med vsem mojim ljudstvom, da greš, da si vzameš ženo izmed neobrezanih Filistejcev?« Samson je rekel svojemu očetu: »Njo mi vzemi, kajti ta mi ugaja.«',
        4: 'Toda njegov oče in njegova mati nista vedela, da je bilo to od Gospoda, da je iskal priložnost zoper Filistejce, kajti ob tistem času so imeli Filistejci gospostvo nad Izraelom.',
        5: 'Potem so Samson, njegov oče in njegova mati odšli dol v Timno in prišli do timnatskih vinogradov in glej, proti njemu je zarjovel mlad lev.',
        6: 'Gospodov Duh je mogočno prišel nadenj in raztrgal ga je, kakor bi raztrgal kozliča in ničesar ni imel v svoji roki, toda svojemu očetu ali svoji materi ni povedal, kaj je storil.',
        7: 'Odšel je dol in govoril z žensko in Samsonu je ugajala.',
        8: 'Čez nekaj časa se je vrnil, da jo vzame in zavil je stran, da pogleda levje truplo in glej, tam je bil roj čebel in med v levjem truplu.',
        9: 'Od tega je vzel v svoje roke in jedoč šel naprej in prišel k svojemu očetu in materi ter jima dal in onadva sta jedla. Toda ni jima povedal, da je med vzel iz levjega trupla.',
        10: 'Tako je njegov oče odšel dol k ženski in Samson je tam priredil zabavo, kajti tako so imeli mladeniči navado delati.',
        11: 'Pripetilo se je, ko so ga zagledali, da so privedli trideset družabnikov, da bi bili z njim.',
        12: 'Samson jim je rekel: »Sedaj vam bom zastavil uganko. Če mi jo lahko v sedmih dneh praznovanja zagotovo razodenete in jo odkrijete, potem vam bom dal trideset rjuh in trideset zamenjav oblek,',
        13: 'toda če mi je ne morete oznaniti, potem mi boste vi dali trideset rjuh in trideset zamenjav oblek.« Rekli so mu: »Zastavi svojo uganko, da jo bomo lahko slišali.«',
        14: 'Rekel jim je: »Iz jedca je prišla hrana in iz močnega je izšla sladkost.« In v treh dneh niso mogli pojasniti uganke.',
        15: 'Pripetilo se je na sedmi dan, da so Samsonovi ženi rekli: »Premami svojega soproga, da nam lahko oznani uganko, sicer bomo tebe in hišo tvojega očeta zažgali z ognjem. Ali ste nas poklicali, da vzamete kar imamo? Mar ni tako?«',
        16: 'Samsonova žena je jokala pred njim ter rekla: »Ti me le sovražiš in me ne ljubiš. Otrokom mojega ljudstva si zastavil uganko, meni pa je nisi povedal.« Rekel ji je: »Glej, nisem je povedal svojemu očetu niti svoji materi in jo bom povedal tebi?«',
        17: 'Pred njim je jokala sedem dni, dokler je trajala njihova zabava in pripetilo se je na sedmi dan, da ji je povedal, ker je boleče pritiskala nanj in uganko je povedala otrokom svojega ljudstva.',
        18: 'Možje iz mesta so mu sedmi dan, preden je sonce zašlo, rekli: »Kaj je slajše od meda? In kaj je močnejše kakor lev?« Rekel jim je: »Če ne bi orali z mojo telico, ne bi odkrili moje uganke.«',
        19: 'In Gospodov Duh je prišel nadenj in odšel je dol v Aškelón in izmed njih usmrtil trideset mož, vzel njihov plen in dal zamenjavo oblačil tistim, ki so pojasnili uganko. Njegova jeza je bila vžgana in odšel je gor do hiše svojega očeta.',
        20: 'Toda Samsonova žena je bila dana njegovemu družabniku, ki ga je uporabil kakor svojega prijatelja.',
    },
    15: {
        1: 'Toda pripetilo se je čez nekaj časa, ob času pšenične žetve, da je Samson s kozličem obiskal svojo ženo in rekel: »Šel bom noter k svoji ženi v sobo.« Toda njen oče mu ni dovolil vstopiti.',
        2: 'Njen oče je rekel: »Resnično sem mislil, da si jo popolnoma zasovražil, zato sem jo dal tvojemu družabniku. Mar ni njena mlajša sestra boljša od nje? Vzemi njo, prosim te, namesto nje.«',
        3: 'Samson je glede njih rekel: »Sedaj bom bolj brez krivde kakor Filistejci, čeprav jim storim zlo.«',
        4: 'Samson je odšel in ujel tristo lisic in vzel kose tlečega lesa in obrnil rep k repu in kos tlečega lesa položil v sredo med dva repa.',
        5: 'Ko je kose tlečega lesa zažgal, jih je spustil v stoječe žito Filistejcev in zažgal tako snope, kot tudi stoječe žito, z vinogradi in oljkami.',
        6: 'Potem so Filistejci rekli: »Kdo je to storil?« Odgovorili so: »Samson, zet Timnčana, ker je ta vzel njegovo ženo in jo dal njegovemu družabniku.« In Filistejci so prišli gor in z ognjem zažgali njo in njenega očeta.',
        7: 'Samson jim je rekel: »Čeprav ste to storili, se vam bom vendarle maščeval in potem bom odnehal.«',
        8: 'Udaril jih je, golen in stegno, z velikim pokolom in odšel dol ter prebival na vrhu skale Etám.',
        9: 'Potem so Filistejci odšli gor, se utaborili v Judu in se razširili v Lehi.',
        10: 'Možje iz Juda so rekli: »Zakaj ste prišli gor zoper nas?« Odgovorili so: »Gor smo prišli, da zvežemo Samsona, da mu storimo, kakor je on storil nam.«',
        11: 'Potem je tri tisoč mož iz Juda odšlo na vrh skale Etám in reklo Samsonu: »Mar ne veš, da so Filistejci vladarji nad nami? Kaj je to, kar si nam storil?« Rekel jim je: »Kakor so storili meni, tako sem jaz storil njim.«',
        12: 'Rekli so mu: »Prišli smo dol, da te zvežemo, da te lahko izročimo v roko Filistejcev.« Samson jim je rekel: »Prisezite mi, da vi sami ne boste padli name.«',
        13: 'Odgovorili so mu, rekoč: »Ne, temveč te bomo trdno zvezali in te izročili v njihovo roko, toda mi te zagotovo ne bomo ubili.« Zvezali so ga z dvema novima vrvema in ga od skale privedli gor.',
        14: 'Ko je prišel v Lehi, so Filistejci zavpili zoper njega in nadenj je mogočno prišel Gospodov Duh in vrvi, ki so bile na njegovih laktih, so postale kakor lan, ki je bil zažgan z ognjem in njegove vezi so se sprostile iz njegovih rok.',
        15: 'Našel je novo oslovsko čeljustnico, iztegnil svojo roko, jo vzel in z njo usmrtil tisoč mož.',
        16: 'Samson je rekel: »Z oslovsko čeljustnico, kupi na kupe, z oslovsko čeljustjo sem umoril tisoč mož.«',
        17: 'Ko je končal z govorjenjem, se je pripetilo, da je iz svoje roke odvrgel čeljustnico in ta kraj imenoval Ramát Lehi.',
        18: 'Bil pa je silno žejen in klical h Gospodu ter rekel: »Ti si dal to veliko osvoboditev v roko svojega služabnika in sedaj ali naj umrem od žeje in padem v roko neobrezancev?«',
        19: '§ Toda Bog je razklal votel kraj, ki je bil v Čestjustnici in iz njega je pritekla voda. Ko jo je pil, je njegov duh ponovno prišel in bil je oživljen. Zato je njegovo ime imenoval En Koré, ki je v Lehiju, do današnjega dne.',
        20: 'V dneh Filistejcev je Izraelu sodil dvajset let.',
    },
    16: {
        1: 'Potem je Samson odšel v Gazo in tam videl pocestnico in šel noter k njej.',
        2: 'To je bilo povedano prebivalcem Gaze, rekoč: »Samson je prišel sèm.« Obkolili so ga in vso noč prežali nanj v velikih vratih mesta in vso noč so mirovali, rekoč: »Zjutraj, ko je dan, ga bomo umorili.«',
        3: 'Samson je ležal do polnoči, ob polnoči pa je vstal, vzel vrata velikih vrat mesta in dva podboja in z njimi odšel proč, zapah in vse in si jih naložil na svoje rame in jih odnesel gor na vrh hriba, ki je pred Hebrónom.',
        4: 'Potem se je pripetilo, da je ljubil žensko v dolini Sorék, ki ji je bilo ime Dalíla.',
        5: 'Filistejski knezi so prišli gor k njej in ji rekli: »Premami ga in poglej kje tiči njegova velika moč in s kakšnimi sredstvi bi lahko prevladali zoper njega, da bi ga lahko zvezali, da ga oslabimo, mi pa ti bomo dali, vsak izmed nas, tisoč sto koščkov srebra.«',
        6: 'Dalíla je rekla Samsonu: »Povej mi, prosim te, kje leži tvoja velika moč in s čim bi bil lahko zvezan, da se te oslabi.«',
        7: 'Samson ji je rekel: »Če me zvežejo s sedmimi zelenimi vrvmi, ki niso bile nikoli posušene, potem bom slaboten in bom kakor drug človek.«',
        8: 'Potem so filistejski knezi gor k njej prinesli sedem zelenih vrvi, ki niso bile posušene in ona ga je z njimi zvezala.',
        9: 'Torej tam so v zasedi prežali možje, ki so z njo ostajali v sobi. Rekla mu je: »Filistejci nadte Samson.« Potrgal je vrvi, kakor se pretrga nit prediva, ko se dotakne ognja. Tako njegova moč ni bila poznana.',
        10: 'Dalíla je rekla Samsonu: »Glej, zasmehoval si me in mi govoril laži. Sedaj mi povej, prosim te, s čim bi bil lahko zvezan.«',
        11: 'Rekel ji je: »Če bi me trdno zvezali z novimi vrvmi, ki niso bile nikoli uporabljene, potem bi bil šibek in bi bil kakor drug človek.«',
        12: 'Zato je Dalíla vzela nove vrvi, ga z njimi zvezala in mu rekla: »Filistejci nadte Samson.« In tam so bili prežavci v zasedi, ki so ostajali v sobi. In potrgal jih je iz svojih rok kakor nit.',
        13: 'Dalíla je rekla Samsonu: »Doklej si me zasmehoval in mi govoril laži. Povej mi s čim naj bi bil zvezan.« Rekel ji je: »Če stkeš sedem pramenov moje glave s tkalčjim osnutkom.«',
        14: 'In pritrdila ga je z iglo in mu rekla: »Filistejci nadte Samson.« Prebudil se je iz svojega spanja in odšel s tkalsko iglo in s tkalčjim osnutkom.',
        15: 'Rekla mu je: »Kako lahko rečeš: ›Ljubim te,‹ ko tvoje srce ni z menoj?« Že trikrat si me zasmehoval in mi nisi povedal, v čem leži tvoja velika moč.',
        16: 'Ko ga je dnevno pritiskala s svojimi besedami in ga silila, tako da je bila njegova duša vznemirjena do smrti, se je pripetilo,',
        17: 'da ji je izpovedal vse svoje srce in ji rekel: »Britev ni prišla na mojo glavo, kajti bil sem nazirec Bogu od maternice svoje matere. Če bom obrit, potem bo moja moč odšla od mene in postanem slaboten in bom podoben kateremukoli drugemu človeku.«',
        18: 'Ko je Dalíla videla, da ji je izpovedal vse svoje srce, je poslala in dala poklicati filistejske kneze, rekoč: »Pridite tokrat gor, kajti razodel mi je vse svoje srce.« Potem so gor k njej prišli gospodarji Filistejcev in v svoji roki prinesli denar.',
        19: 'Pripravila ga je, da je zaspal na njenih kolenih in dala poklicati moža, da mu iz njegove glave odstriže sedem pramenov in ga začela poniževati in njegova moč je odšla od njega.',
        20: 'Rekla je: »Filistejci nadte Samson.« Prebudil se je iz svojega spanja in rekel: »Šel bom ven kakor ob drugih časih poprej in se stresel.« Ni pa vedel, da je Gospod odšel od njega.',
        21: 'Toda Filistejci so ga prijeli in iztaknili njegove oči in ga privedli dol v Gazo in ga zvezali z bronastimi okovi in mlel je v jetnišnici.',
        22: 'Vendar so potem, ko je bil ostrižen, lasje njegove glave začeli ponovno rasti.',
        23: 'Potem so se filistejski knezi zbrali skupaj, da svojemu bogu Dagónu darujejo veliko klavno daritev in da se veselijo, kajti rekli so: »Naš bog je v našo roko izročil našega sovražnika Samsona.«',
        24: 'Ko ga je ljudstvo zagledalo, so hvalili svojega boga, kajti rekli so: »Naš bog je v naše roke izročil našega sovražnika in uničevalca naše dežele, ki je umoril številne izmed nas.«',
        25: 'Pripetilo pa se je, ko so bila njihova srca vesela, da so rekli: »Pokličite Samsona, da nam bo lahko naredil zabavo.« Iz jetnišnice so dali poklicati Samsona in naredil jim je zabavo. Postavili so ga med stebre.',
        26: 'Samson pa je rekel dečku, ki ga je držal za roko: »Dopusti mi, da lahko čutim stebre, na katerih stoji hiša, da se lahko naslonim nanje.«',
        27: 'Torej hiša je bila polna mož in žena in vsi filistejski knezi so bili tam in tam je bilo na strehi okoli tri tisoč mož in žena, ki so gledali, medtem ko jih je Samson zabaval.',
        28: 'Samson pa je zaklical h Gospodu in rekel: »Oh Gospod Bog, spomni se me, prosim te in okrepi me, prosim te, samo [še] tokrat, oh Bog, da se bom lahko takoj maščeval Filistejcem za svoji dve očesi.«',
        29: 'Samson se je oklenil dveh srednjih nosilnih stebrov, na katerih, je slonela hiša, na enega s svojo desnico in na drugega s svojo levico.',
        30: 'Samson je rekel: »Naj umrem s Filistejci.« Z vso svojo močjo se je sklonil in hiša je padla na kneze in na vse ljudstvo, ki je bilo v njej. Tako je bilo mrtvih, ki jih je usmrtil ob svoji smrti, več kakor tistih, ki jih je usmrtil v svojem življenju.',
        31: 'Potem so njegovi bratje in vsa hiša njegovega očeta prišli dol, ga vzeli in ga prinesli gor ter ga pokopali med Coro in Eštaólom, na grobišču njegovega očeta Manóaha. Izraelu je sodil dvajset let.',
    },
    17: {
        1: 'Tam je bil mož z gore Efrájim, katerega ime je bilo Miha.',
        2: 'Ta je rekel svoji materi: »Tisoč sto šeklov srebra, ki so bili vzeti od tebe, glede katerih si preklinjala in glede katerih si govorila tudi v moja ušesa, glej, srebro je z menoj. Jaz sem ga vzel.« Njegova mati je rekla: »Blagoslovljen bodi od Gospoda, moj sin.«',
        3: 'Ko je svoji materi povrnil tisoč sto šeklov srebra, je njegova mati rekla: »Srebro sem v celoti posvetila Gospodu, od svoje roke za svojega sina, da se naredi rezana podoba in ulita podoba. Sedaj ti ga bom torej povrnila.«',
        4: 'Vendar je denar vrnil svoji materi in njegova mati je vzela dvesto šeklov srebra in jih dala livarju, ki je iz njih naredil rezano podobo in ulito podobo in bili sta v Mihovi hiši.',
        5: 'Mož Miha je imel hišo bogov in naredil efód in družinskega malika in uméstil enega izmed svojih sinov, ki je postal njegov duhovnik.',
        6: 'V tistih dneh ni bilo kralja v Izraelu, temveč je vsak človek počel to, kar je bilo pravilno v njegovih lastnih očeh.',
        7: 'Tam je bil mladenič iz Judovega Betlehema, iz Judove družine, ki je bil Lévijevec in se je mudil tam.',
        8: 'Človek je odrinil iz mesta, iz Judovega Betlehema, da začasno prebiva, kjer bi lahko našel prostor in ko je potoval, je prišel do gore Efrájim, k Mihovi hiši.',
        9: 'Miha mu je rekel: »Od kod prihajaš?« Odgovoril mu je: »Jaz sem Lévijevec iz Judovega Betlehema in grem, da začasno prebivam tam, kjer bom lahko našel prostor.«',
        10: 'Miha mu je rekel: »Prebivaj z menoj in bodi mi oče in duhovnik, jaz pa ti bom ob letu dajal deset šeklov srebra in opremo oblačila in živež.« Tako je Lévijevec vstopil.',
        11: 'Lévijevec je bil zadovoljen, da prebiva z možem in mladenič mu je bil kakor eden izmed njegovih sinov.',
        12: 'Miha je uméstil Lévijevca in mladenič je postal njegov duhovnik in bil je v Mihovi hiši.',
        13: 'Potem je Miha rekel: »Sedaj vem, da mi bo Gospod storil dobro, glede na to, da imam Lévijevca za svojega duhovnika.«',
    },
    18: {
        1: 'V tistih dneh ni bilo kralja v Izraelu in v tistih dneh si je rod Danovcev iskal dediščino, da v njej prebiva, kajti do tistega dne jim vsa njihova dediščina ni pripadla med Izraelovimi rodovi.',
        2: 'Danovi otroci so izmed svojih družin poslali pet moških iz svojih pokrajin, junaške može iz Core in iz Eštaóla, da hodijo vzdolž dežele in da jo preiščejo. Rekli so jim: »Pojdite, oglejte deželo.« Ko so le-ti prišli do gore Efrájim, k Mihovi hiši, so se tam nastanili.',
        3: 'Ko so bili pri Mihovi hiši, so prepoznali glas mladeniča, Lévijevca. Obrnili so se tja in mu rekli: »Kdo te je privedel sèm? Kaj delaš na tem kraju? In kaj imaš tukaj?«',
        4: 'Odgovoril jim je: »Tako in tako je Miha postopal z menoj, me najel in sem njegov duhovnik.«',
        5: 'Rekli so mu: »Prosimo te, vprašaj za nasvet od Boga, da bomo lahko vedeli katera izmed naših poti, po kateri gremo, bo uspešna.«',
        6: 'Duhovnik jim je rekel: »Pojdite v miru. Vaša pot, po kateri greste, je pred Gospodom.«',
        7: 'Potem je pet mož odpotovalo in prišlo k Láješu in videlo ljudstvo, ki je bilo tam, kako so brezskrbno prebivali po navadi Sidóncev, tiho in varno. Tam v deželi ni bilo naseljencev, da bi jih lahko v kakršnikoli stvari osramotili. Bili so daleč od Sidóncev in z nikomer niso imeli nič opraviti.',
        8: 'Prišli so k svojim bratom do Core in Eštaóla in njihovi bratje so jim rekli: »Kaj pravite?«',
        9: 'Odgovorili so: »Vstanite, da bomo lahko šli gor zoper njih, kajti videli smo deželo in glejte, ta je zelo dobra. In vi ste mirni? Ne bodite leni, da bi šli in vstopili, da vzamete deželo v last.«',
        10: 'Ko greste, boste prišli k varnemu ljudstvu in k veliki deželi, kajti Bog jo je dal v vaše roke. Prostor, kjer ni pomanjkanja česarkoli, kar je na zemlji.',
        11: 'Od tod je odšla družina Danovcev na svojo pot, iz Core in iz Eštaóla, šeststo mož, opasanih z bojnim orožjem.',
        12: 'Odšli so gor in se utaborili v Kirját Jearímu v Judu. Zato so ta kraj imenovali Mahané Dan do današnjega dne. Glej ta je poleg Kirját Jearíma.',
        13: 'Od tam so prešli h gori Efrájim in prišli do Mihove hiše.',
        14: 'Potem je pet mož, ki so odšli, da ogledajo deželo Láješ, odgovorilo in reklo svojim bratom: »Ali veste, da so v teh hišah efód, družinski malik, rezana podoba in ulita podoba? Sedaj torej preudarite kaj vam je storiti.«',
        15: 'Obrnili so se tja in prišli do hiše mladeniča, Lévijevca, torej k Mihovi hiši in ga pozdravili.',
        16: 'Šeststo mož, opasanih s svojimi bojnimi orožji, ki so bili izmed Danovih otrok, pa je stalo pri vhodu velikih vrat.',
        17: 'Pet mož, ki so šli, da ogledajo deželo, je odšlo gor in vstopili so tja in vzeli rezano podobo, efód, družinskega malika in ulito podobo. Duhovnik pa je stal na vhodu velikih vrat s šeststotimi možmi, ki so bili opasani z bojnim orožjem.',
        18: 'Ti so odšli v Mihovo hišo in prinesli izrezljano podobo, efód, družinskega malika in ulito podobo. Potem jim je duhovnik rekel: »Kaj počnete?«',
        19: 'Rekli so mu: »Molči, svojo roko položi na svoja usta in pojdi z nami in nam bodi oče in duhovnik. Ali je zate bolje biti duhovnik hiši enega človeka ali da postaneš duhovnik rodu in družini v Izraelu?«',
        20: 'Duhovnikovo srce je bilo veselo in vzel je efód, družinskega malika, rezano podobo in odšel v sredo ljudstva.',
        21: 'Tako so se obrnili in odšli ter predse postavili malčke, živino in vozove.',
        22: 'In ko so bili dobro pot od Mihove hiše, so se ljudje, ki so bili v hišah blizu Mihove hiše, zbrali skupaj in dohiteli Danove otroke.',
        23: 'Klicali so k Danovim otrokom. Ti pa so obrnili svoje obraze in Mihu rekli: »Kaj te pesti, da prihajaš s takšnim spremstvom?«',
        24: 'Odgovoril je: »Odvzeli ste moje bogove, ki sem jih naredil in duhovnika ter odšli proč. In kaj še imam? Kaj je to, da mi pravite: ›Kaj te pesti?‹«',
        25: 'Danovi otroci so mu rekli: »Tvojega glasu naj ne bo slišati med nami, da ne bi jezni ljudje stekli nadte in bi izgubil svoje življenje, z življenji svoje družine.«',
        26: 'Danovi otroci so odšli svojo pot. Ko je Miha videl, da so bili premočni zanj, se je obrnil in se vrnil nazaj k svoji hiši.',
        27: 'Vzeli so stvari, ki jih je naredil Miha in duhovnika, ki ga je imel in prišli k Láješu, k ljudstvu, ki je bilo tiho in varno. Udarili so jih z ostrino meča in mesto zažgali z ognjem.',
        28: 'Tam ni bilo nobenega osvoboditelja, ker je bilo daleč od Sidóna in niso imeli opravka s kakršnimkoli človekom. To je bilo v dolini, ki leži pri Bet Rehóbu. In zgradili so mesto ter prebivali v njem.',
        29: 'Ime mesta so imenovali Dan, po imenu njihovega očeta Dana, ki je bil rojen Izraelu, vendar je bilo ime mesta najprej Láješ.',
        30: 'Danovi otroci so postavili rezano podobo in Jonatan, sin Geršóma, sinú Manáseja, on in njegovi sinovi so bili duhovniki Danovemu rodu do dneva ujetništva dežele.',
        31: 'Postavili so si Mihovo rezano podobo, ki jo je naredil ves ta čas, ko je bila Božja hiša v Šilu.',
    },
    19: {
        1: 'Pripetilo se je v tistih dneh, ko ni bilo kralja v Izraelu, da je bil tam nek Lévijevec, [ki je] začasno prebival na pobočju gore Efrájim, ki si je vzel priležnico iz Judovega Betlehema.',
        2: 'Njegova priležnica je zoper njega igrala vlačugo in odšla proč od njega, v hišo svojega očeta v Judovem Betlehemu in bila tam cele štiri mesece.',
        3: 'Njen soprog je vstal in odšel za njo, da ji prijateljsko govori in da jo ponovno privede. S seboj je imel svojega služabnika in nekaj oslov in privedla ga je v hišo svojega očeta. Ko ga je oče od gospodične zagledal, se je razveselil, da ga je srečal.',
        4: 'Njegov tast, oče od gospodične, ga je zadržal in z njimi je ostal tri dni. Tako so jedli in pili ter tam prenočevali.',
        5: 'Pripetilo se je na četrti dan, ko so zgodaj zjutraj vstali, da se je dvignil, da odide. Oče od gospodične pa je svojemu zetu rekel: »Potolaži svoje srce z grižljajem kruha in potem pojdi svojo pot.«',
        6: 'Oba skupaj sta se usedla, jedla in pila, kajti oče od gospodične je možu rekel: »Privoli, prosim te in ostani vso noč in naj bo tvoje srce veselo.«',
        7: 'Ko je mož vstal, da odide, mu je tast prigovarjal, zato je tam ponovno prenočil.',
        8: 'Vstal je zgodaj zjutraj, peti dan, da odide in oče od gospodične je rekel: »Potolaži svoje srce, prosim te.« Ostala sta do popoldneva in oba sta jedla.',
        9: 'Ko je mož vstal, da odide, on, njegova priležnica in njegov služabnik, mu je tast, oče od gospodične, rekel: »Glej, sedaj se dan približuje večeru. Prosim te, ostani vso noč. Glej, dan gre h koncu, prenočuj tukaj, da bo tvoje srce lahko veselo in naslednji dan zgodaj pojdi na svojo pot, da boš lahko šel domov.«',
        10: 'Toda mož to noč ni hotel ostati, temveč je vstal, odšel in prišel nasproti Jebúsa, ki je Jeruzalem in tam sta bila z njim dva osedlana osla in tudi njegova priležnica je bila z njim.',
        11: 'In ko so bili pri Jebúsu, je bil dan že davno porabljen in služabnik je rekel svojemu gospodarju: »Pridi, prosim te in obrniva se v to mesto Jebusejcev in prenočiva v njem.«',
        12: 'Njegov gospodar pa mu je rekel: »Ne bomo zavili vstran, sèm v to mesto tujca, ki ni izmed Izraelovih otrok; prešli bomo do Gíbee.«',
        13: 'Svojemu služabniku je rekel: »Pridi in približajmo se enemu izmed teh mest, da vso noč prenočimo v Gíbei ali v Rami.«',
        14: 'Šli so naprej svojo pot in sonce je zašlo nad njimi, ko so bili pri Gíbei, ki pripada Benjaminu.',
        15: 'Obrnili so se tja, da vstopijo in prenočijo v Gíbei. Ko so vstopili, se je usedel na mestno ulico, kajti tam ni bilo nobenega človeka, ki bi jih vzel v svojo hišo, da prenočijo.',
        16: 'Glej, zvečer je prišel starec od svojega dela zunaj na polju, ki je bil prav tako z gore Efrájim in je začasno prebival v Gíbei. Toda možje kraja so bili Benjaminovci.',
        17: 'Ko je povzdignil svoje oči, je na mestni ulici zagledal popotnika in starec je rekel: »Kam greš? In od kod prihajaš?«',
        18: 'Ta mu je odgovoril: »Mi smo prešli iz Judovega Betlehema proti pobočju gore Efrájim. Od tam sem in odšel sem k Judovemu Betlehemu, toda sedaj grem h Gospodovi hiši. Tukaj pa ni nobenega moža, ki bi me sprejel v hišo.',
        19: 'Vendar je tukaj tako slama in krma za naša osla in tukaj je kruh in vino zame in za mojo pomočnico in za mladeniča, ki je s tvojimi služabniki. Tukaj ni potrebe po nobeni stvari.«',
        20: 'Starec je rekel: »Mir bodi s teboj. Kakorkoli, pusti vse svoje potrebe počivati na meni, samo ne prenočuj na ulici.«',
        21: 'Tako ga je odvedel v svojo hišo in dal krmo k oslom. Umili so svoja stopala, jedli in pili.',
        22: 'Torej ko so razveseljevali svoja srca, glej, so možje iz mesta, neki Beliálovi sinovi, naokoli obkrožili hišo in udarjali na vrata ter hišnemu gospodarju, starcu, spregovorili, rekoč: »Privedi moškega, ki je prišel v tvojo hišo, da ga lahko spoznamo.«',
        23: 'Mož, hišni gospodar, je odšel ven k njim ter jim rekel: »Ne, moji bratje, ne, prosim vas, ne storite tako zlobno, glede na to, da je ta mož prišel v mojo hišo, ne storite te neumnosti.',
        24: 'Glejte, tukaj je moja hči, devica in njegova priležnica. Njiju bom torej privedel ven in ju ponižajte ter z njima storite kar se vam zdi dobro, toda temu možu ne storite tako ogabne stvari.«',
        25: 'Toda možje mu niso hoteli prisluhniti. Tako je mož vzel svojo priležnico in jo privedel k njim. Spoznali so jo in jo zlorabljali vso noč do jutra. Ko pa se je dan začel svitati, so jo pustili oditi.',
        26: 'Potem je ob jutranjem svitanju ženska prišla in padla dol pri vratih moževe hiše, kjer je bil njen gospodar, dokler ni bilo svetlo.',
        27: 'Njen gospodar je zjutraj vstal, odprl vrata hiše in odšel ven, da gre svojo pot. In glej, ženska, njegova priležnica, je bila zvrnjena dol pri hišnih vratih in njene roke so bile na pragu.',
        28: 'Rekel ji je: »Vstani in pojdimo.« Toda ni se odzvala. Potem jo je mož vzel gor na osla in mož se je dvignil ter se spravil k svojemu kraju.',
        29: 'Ko je prišel v svojo hišo, je vzel nož in ga položil na svojo priležnico in jo razdelil na dvanajst kosov, skupaj z njenimi kostmi in jo poslal po vseh Izraelovih pokrajinah.',
        30: 'In bilo je tako, da so vsi, ki so to videli, rekli: »Takšnega dejanja ni bilo storjenega niti videnega od dneva, ko so Izraelovi otroci prišli gor iz egiptovske dežele, do današnjega dne. Preudarite o tem, sprejmite nasvet in govorite svojim umom.«',
    },
    20: {
        1: 'Potem so vsi Izraelovi otroci odšli ven in skupnost je bila zbrana skupaj kakor en mož, od Dana, celo do Beeršébe, z gileádsko deželo, h Gospodu v Micpi.',
        2: 'Vodje izmed vsega ljudstva, torej izmed vseh Izraelovih rodov, so se predstavili v zboru Božjega ljudstva, štiristo tisoč pešcev, ki so izdirali meč.',
        3: '(Torej Benjaminovi otroci so slišali, da so Izraelovi otroci odšli gor do Micpe.) Potem so Izraelovi otroci rekli: »Povej nam, kako je bila ta zlobnost?«',
        4: 'Lévijevec, soprog ženske, ki je bila umorjena, je odgovoril in rekel: »Prišel sem v Gíbeo, ki pripada Benjaminu, jaz in moja priležnica, da prenočiva.',
        5: 'Možje iz Gíbee pa so vstali zoper mene in ponoči obdali hišo naokoli mene in me mislili umoriti. Mojo priležnico pa so posilili, da je mrtva.',
        6: 'Vzel sem svojo priležnico, jo razsekal na kose in jo razposlal po vsej deželi Izraelove dediščine, kajti v Izraelu so zagrešili nespodobnost in neumnost.',
        7: 'Glejte, vi vsi ste Izraelovi otroci, dajte tukaj svojo besedo in nasvet.«',
        8: 'Vse ljudstvo je vstalo kakor en mož, rekoč: »Nobeden izmed nas ne bo šel k svojemu šotoru niti se nobeden izmed nas ne bo obrnil v svojo hišo.',
        9: 'Toda sedaj bo to stvar, ki jo bomo storili Gíbei. Šli bomo gor po žrebu zoper njo',
        10: 'in vzeli bomo po vseh Izraelovih rodovih deset mož izmed sto in sto izmed tisoč in tisoč izmed deset tisoč, da prinesejo živež za ljudstvo, da bodo lahko delali, ko pridejo v Benjaminovo Gíbeo, glede na vso neumnost, ki so jo oni storili v Izraelu.«',
        11: 'Tako so bili vsi Izraelovi možje, zbrani zoper mesto, povezani skupaj kakor en mož.',
        12: 'Izraelovi rodovi so poslali može skozi ves Benjaminov rod, rekoč: »Kakšna zlobnost je ta, ki je bila storjena med vami?',
        13: 'Zdaj nam torej izročite može, Beliálove otroke, ki so v Gíbei, da jih lahko usmrtimo in iz Izraela odstranimo zlo.« Toda Benjaminovi otroci niso hoteli prisluhniti glasu njihovih bratov, Izraelovih otrok,',
        14: 'temveč so se Benjaminovi otroci zbrali skupaj iz vseh mest v Gíbeo, da gredo ven, da se bojujejo zoper Izraelove otroke.',
        15: 'Benjaminovi otroci so bili ob tistem času prešteti iz mest, šestindvajset tisoč mož, ki so izdirali meč, poleg prebivalcev Gíbee, katerih je bilo preštetih sedemsto izbranih mož.',
        16: 'Med vsem tem ljudstvom je bilo tam sedemsto izbranih mož, ki so bili levični. Vsak je lahko metal kamne za las natančno in ni zgrešil.',
        17: 'Mož iz Izraela, poleg Benjamina, je bilo preštetih štiristo tisoč mož, ki so izdirali meč. Vsi ti so bili bojevniki.',
        18: 'Izraelovi otroci so vstali in odšli gor h Gospodovi hiši in vprašali za nasvet od Boga ter rekli: »Kdo izmed nas bo prvi šel gor v bitko zoper Benjaminove otroke?« Gospod je rekel: »Juda bo prvi šel gor.«',
        19: 'Izraelovi otroci so zjutraj vstali in se utaborili zoper Gíbeo.',
        20: 'Izraelovi možje so odšli ven, da se bojujejo zoper Benjamina. Izraelovi možje so se razvrstili, da se bojujejo zoper te v Gíbei.',
        21: 'Benjaminovi otroci so prišli ven iz Gíbee in izmed Izraelcev ta dan do tal uničili dvaindvajset tisoč mož.',
        22: 'Ljudstvo Izraelovih mož se je ohrabrilo in svojo bitko ponovno razvrstilo na kraju, kjer so se razvrstili prvi dan.',
        23: '(Izraelovi otroci so odšli gor in do večera jokali pred Gospodom in prosili Gospoda za nasvet, rekoč: »Ali naj grem ponovno gor v bitko zoper otroke Benjamina, svojega brata?« Gospod je rekel: »Pojdite gor zoper njih.«)',
        24: 'Izraelovi otroci so se drugi dan približali zoper Benjaminove otroke.',
        25: 'Benjamin je drugi dan odšel naprej, ven iz Gíbee, zoper njih in izmed Izraelovih otrok do tal ponovno uničil osemnajst tisoč mož. Vsi ti so izdirali meč.',
        26: 'Potem so vsi Izraelovi otroci in vse ljudstvo odšli gor in prišli k Božji hiši, jokali in tam sedeli pred Gospodom in se ta dan postili do večera in pred Gospodom darovali žgalne daritve in mirovne daritve.',
        27: 'Izraelovi otroci so poizvedeli od Gospoda (kajti skrinja Božje zaveze je bila v tistih dneh tam',
        28: 'in Pinhás, sin Eleazarja, sinú Arona, je v tistih dneh stal pred njo), rekoč: »Ali naj grem ponovno ven v bitko zoper otroke Benjamina, svojega brata ali naj odneham?« Gospod je rekel: »Pojdi gor, kajti jutri ti jih bom izročil v roko.«',
        29: 'Izrael je okoli Gíbee postavil prežavce v zasedi.',
        30: 'Izraelovi otroci so na tretji dan odšli gor zoper Benjaminove otroke in se kakor poprej razvrstili zoper Gíbeo.',
        31: 'Benjaminovi otroci so odšli ven zoper ljudstvo in bili so odvlečeni od mesta in začeli udarjati izmed ljudstva in ubili trideset mož iz Izraela, kakor poprej na glavnih cestah, od katerih gre ena gor k Božji hiši, druga pa h Gíbei na polje.',
        32: 'Benjaminovi otroci so rekli: »Udarjeni so pred nami kakor poprej.« Toda Izraelovi otroci so rekli: »Bežimo in jih od mesta potegnimo h glavnim cestam.«',
        33: 'Vsi Izraelovi možje so se dvignili iz svojega kraja in se razvrstili pri Báal Tamari. Izraelovi prežavci v zasedi pa so prišli naprej iz svojih krajev, torej iz travnikov Gíbee.',
        34: 'Tam je prišlo zoper Gíbeo deset tisoč izbranih mož iz vsega Izraela in bitka je bila huda. Toda niso vedeli, da je bilo zlo blizu njih.',
        35: 'Gospod je udaril Benjamina pred Izraelom in Izraelovi otroci so izmed Benjaminovcev ta dan uničili petindvajset tisoč in sto mož. Vsi ti so izdirali meč.',
        36: 'Tako so Benjaminovi otroci videli, da so bili udarjeni, kajti možje iz Izraela so dali prostor Benjaminovcem, ker so zaupali v prežavce v zasedi, ki so jih postavili poleg Gíbee.',
        37: 'Prežalci v zasedi so pohiteli in navalili na Gíbeo in prežavci v zasedi so šli vzdolž in vse mesto udarili z ostrino meča.',
        38: 'Torej tam je bilo določeno znamenje med Izraelovimi možmi in prežavci v zasedi, da naj bi naredili velik plamen z dimom, ki se vzdiguje iz mesta.',
        39: 'Ko so se Izraelovi možje obrnili v bitko, je Benjamin začel udarjati in izmed Izraelovih mož ubil okoli trideset oseb, kajti rekli so: »Zagotovo so udarjeni pred nami kakor v prvi bitki.«',
        40: 'Toda ko se je plamen s stebrom dima začel dvigovati iz mesta, so Benjaminovci pogledali za seboj in glej, plamen mesta se je vzdigoval k nebu.',
        41: 'Ko so se Izraelovi možje ponovno obrnili, so bili možje Benjamina osupli, kajti videli so, da je nadnje prišlo zlo.',
        42: 'Zato so svoje hrbte obrnili pred Izraelovimi možmi na pot divjine, toda bitka jih je dohitela in tiste, ki so prišli iz mest, so uničili v njihovi sredi.',
        43: 'Tako so naokoli obkolili Benjaminovce in jih preganjali in jih z lahkoto pomendrali nasproti Gíbei, proti sončnemu vzhodu.',
        44: 'Tam je iz Benjamina padlo osemnajst tisoč mož. Vsi ti so bili junaški možje.',
        45: 'In obrnili so se in pobegnili proti divjini, k Rimónovi skali. In od njih so zbrali po glavnih cestah pet tisoč mož in trdo so jih zasledovati do Gidóma in jih izmed njih usmrtili dva tisoč.',
        46: 'Tako, da je bilo vseh, ki so ta dan padli iz Benjamina, petindvajset tisoč mož, ki so izdirali meč. Vsi ti so bili junaški možje.',
        47: 'Toda šeststo mož se je obrnilo in pobegnilo v divjino, k Rimónovi skali in v Rimónovi skali so ostali štiri mesece.',
        48: 'Izraelovi možje so se ponovno obrnili nad Benjaminove otroke in jih udarili z ostrino meča, kakor tudi može iz vsakega mesta, tako žival in vse, kar je prišlo k roki. Prav tako so požgali vsa mesta, h katerim so prišli.',
    },
    21: {
        1: 'Torej možje iz Izraela so v Micpi prisegli, rekoč: »Nihče izmed nas svoje hčere ne bo dal Benjaminu za ženo.«',
        2: 'Ljudstvo je prišlo k Božji hiši in tam so ostali do večera pred Bogom in povzdignili svoje glasove in bridko jokali',
        3: 'in rekli: »Oh Gospod, Izraelov Bog, zakaj se je to zgodilo v Izraelu, da danes manjka en rod v Izraelu.«',
        4: 'Pripetilo se je naslednji dan, da je ljudstvo zgodaj vstalo, tam zgradilo oltar in darovalo žgalne daritve in mirovne daritve.',
        5: 'Izraelovi otroci so rekli: »Kdo je tam med vsemi Izraelovimi rodovi, ki s skupnostjo ni prišel gor h Gospodu?« Kajti sklenili so veliko prisego glede tistega, ki ne pride gor h Gospodu v Micpo, rekoč: »Ta bo zagotovo usmrčen.«',
        6: 'Izraelovim otrokom je bilo žal zaradi Benjamina, njihovega brata in rekli so: »Ta dan je iz Izraela iztrebljen en rod.',
        7: 'Kako bomo storili zaradi žena za tiste, ki so ostali, glede na to, da smo pri Gospodu prisegli, da jim ne bomo dali izmed svojih hčera za žene?«',
        8: 'Rekli so: »Kateri izmed Izraelovih rodov je, ki ni prišel v Micpo h Gospodu?« Glej, iz Jabéš Gileáda ni nihče prišel v tabor k zboru.',
        9: 'Kajti ljudstvo je bilo prešteto in glej, tam ni bilo nobenega prebivalca iz Jabéš Gileáda.',
        10: 'Skupnost je tja poslala dvanajst tisoč mož izmed najhrabrejših in jim zapovedala, rekoč: »Pojdite in udarite prebivalce Jabéš Gileáda z ostrino meča, z ženskami in otroki.',
        11: 'To je stvar, ki jo boste storili: ›Popolnoma boste uničili vsakega moškega in vsako žensko, ki je ležala z moškim.‹«',
        12: 'Med prebivalci Jabéš Gileáda so našli štiristo mladih devic, ki nobenega moškega niso spoznale z ležanjem s katerimkoli moškim. Privedli so jih v tabor do Šila, ki je v kánaanski deželi.',
        13: 'Celotna skupnost je poslala nekatere, da govorijo Benjaminovim otrokom, ki so bili v Rimónovi skali in da miroljubno kličejo k njim.',
        14: 'Ob tistem času je ponovno prišel Benjamin in izročili so jim žene, ki so jih žive rešili izmed žensk Jabéš Gileáda in vendar jim to ni zadoščalo.',
        15: 'Ljudstvo se je pokesalo zaradi Benjamina, zato ker je Gospod naredil vrzel v Izraelovih rodovih.',
        16: 'Potem so starešine skupnosti rekli: »Kako bomo storili glede žena za tiste, ki ostanejo, glede na to, da so ženske uničene iz Benjamina?«',
        17: 'Rekli so: » Mora biti dediščina za tiste, ki pobegnejo iz Benjamina, da iz Izraela ne bo uničen rod.«',
        18: 'Vendar jim ne moremo dati žene izmed svojih hčera, kajti Izraelovi otroci so prisegli, rekoč: »Preklet bodi, kdor daje ženo Benjaminu.«',
        19: 'Potem so rekli: »Glej, tam je letno Gospodovo praznovanje v Šilu, na kraju, ki je na severni strani Betela, na vzhodni strani glavne ceste, ki gre gor od Betela do Sihema in na vzhodni strani Lebóne.«',
        20: 'Zato so Benjaminovim otrokom zapovedali, rekoč: »Pojdite in prežite v zasedi v vinogradih.',
        21: 'Glejte in opazujte, če hčere iz Šila pridejo ven, da plešejo v plesih, potem pridite iz vinogradov in zgrabite vsak mož svojo ženo izmed hčera v Šilu in pojdite v Benjaminovo deželo.«',
        22: 'Zgodilo se bo, da ko pridejo k nam njihovi očetje ali njihovi bratje, da se pritožujejo, jim bomo rekli: »Bodite jim naklonjeni zaradi nas, ker v vojni nismo prihranili vsakemu možu svoje žene, kajti ob tistem času jim jih vi niste dali, tako ste sedaj krivi.«',
        23: 'Benjaminovi otroci so tako storili in si vzeli žene, glede na njihovo število izmed tistih, ki so plesale, ki so jih ujeli in odšli ter se vrnili v svojo dediščino in popravili mesta in prebivali v njih.',
        24: 'Ob tem času so Izraelovi otroci odšli od tam, vsak mož k svojemu rodu in k svoji družini in odšli so od tam, vsak mož k svoji dediščini.',
        25: 'V tistih dneh ni bilo kralja v Izraelu. Vsak mož je počel to, kar je bilo pravilno v njegovih lastnih očeh.',
    },
}
